window.TREB_STORY_FACTS = {"P3-F082":{"id":"P3-F082","claim":"Plutarch reports that operating the siege engines required ten thousand pairs of mules every day.","value":"10000","unit":"pairs of mules per day (20,000 animals)","sources":["plutarch1916sulla"],"pin":"Sulla 12.2","quote":"the operation of the siege-engines called for ten thousand pairs of mules, which were employed daily for this service","conf":"Low","conf_note":"Single ancient source; round number; likely rhetorical emphasis on cost.","corr":"","topic":"ST-10; athens-86-siege; logistics"},"P3-F134":{"id":"P3-F134","claim":"The account of the engines comes from the Miracles of St Demetrios, written by Bishop John of Thessalonica.","value":"John","unit":"","sources":["mccotter2003byzantines"],"pin":"text and n. 3","quote":"The bishop who penned the miracles, John, compares the inaccurate rope-pulled devices of the Avars with the accuracy of the Byzantine torsion artillery.","conf":"High","conf_note":"Authorship standard; McCotter cites Lemerle's edition.","corr":"","topic":"ST-16; primary-source; thessalonica-586"},"P3-F017":{"id":"P3-F017","claim":"Sappers made a breach about 30 m long, sapping the wall in two days.","value":"30","unit":"m","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"Sappers in Salah al-Din's army succeeded in making a breach, about thirty metres in length, in the wall which was sapped in two days.","conf":"Medium","conf_note":"Reported dimension; the original unit and chronicle are not given in the web text.","corr":"","topic":"ST-02; jerusalem-1187; mining"},"P3-F005":{"id":"P3-F005","claim":"Arbiv equates two furlongs with about 400 m.","value":"400","unit":"m","sources":["arbiv2023evidence"],"pin":"114–15","quote":"equaling two furlongs (c. 400 m","conf":"Medium","conf_note":"Approximate; depends on the stadion length assumed.","corr":"","topic":"ST-01; units"},"P3-F210":{"id":"P3-F210","claim":"Diodorus reports the helepolis was nine stories high and was moved by 3,400 picked men.","value":"3400","unit":"men","sources":["diodorus1954library"],"pin":"20.91","quote":"Those who were to move the machine were selected from the whole army, three thousand four hundred men excelling in strength","conf":"Low","conf_note":"Single ancient report; large round-ish figure.","corr":"","topic":"ST-27; rhodes-305; helepolis; crews"},"P3-F228":{"id":"P3-F228","claim":"Sparks from the flaming projectile were believed to have ignited the thatched roof.","value":"","unit":"","sources":["leamingtonobserver2015investigation","ihbc2015warwick"],"pin":"IHBC para. 2","quote":"Sparks from the projectile are believed to have ignited the blaze.","conf":"Medium","conf_note":"Eyewitness and press account; castle said cause not yet ascertained.","corr":"medievalhistories2015warwick","topic":"ST-29; incident"},"P3-F035":{"id":"P3-F035","claim":"Murḍā ibn ʿAlī al-Ṭarṣūsī wrote Tabṣirat arbāb al-albāb at Saladin's request, c. 1187 (Zaky).","value":"c. 1187","unit":"date","sources":["zaky1965preliminary"],"pin":"107–9","quote":"on the demand of Sultan Salah el-Din (circa 1187)","conf":"Medium","conf_note":"Dating differs: Fulton (via Purton) c. 1180.","corr":"purton2018review","topic":"ST-05; tarsusi; counterweight-origin"},"P3-F029":{"id":"P3-F029","claim":"Fulton concludes that both Frankish and Muslim forces knew the traction trebuchet by the end of the 11th century.","value":"end of 11th century","unit":"date","sources":["fulton2016artillery"],"pin":"vii","quote":"Both Frankish and Muslim forces were familiar with the traction trebuchet by the end of the eleventh century.","conf":"High","conf_note":"Scholarly conclusion accurately reported.","corr":"","topic":"ST-04; chronology; traction-trebuchet"},"P3-F075":{"id":"P3-F075","claim":"Raymond claims that on the final morning the defenders had nine or ten machines for each crusader machine.","value":"9–10","unit":"machines per crusader machine","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"the Saracens had constructed so many machines that for each one of ours they now had nine or ten","conf":"Low","conf_note":"Single partisan source, likely exaggerated to magnify the victory.","corr":"","topic":"ST-09; jerusalem-1099; artillery"},"P3-F067":{"id":"P3-F067","claim":"The first throw traveled about 170 yards, falling short.","value":"170 (155)","unit":"yd (m)","sources":["nova2000secrets","schupp1998timber"],"pin":"transcript; Schupp para. 11","quote":"The first flew about 170 yards","conf":"High","conf_note":"Both sources agree.","corr":"schupp1998timber","topic":"ST-08; performance-data"},"P3-F078":{"id":"P3-F078","claim":"Jerusalem was captured on 15 July 1099, a Friday.","value":"15 July 1099","unit":"date","sources":["krey1921gesta"],"pin":"Krey 1921 (Fordham web text, Gesta 'The Vision of Peace')","quote":"This city was captured by God's Christians on the fifteenth day of July, the sixth day of the week","conf":"High","conf_note":"Agreed by the Gesta, Raymond (Ides of July) and Fulcher in the same collection.","corr":"raymond1921historia","topic":"ST-09; jerusalem-1099"},"P3-F111":{"id":"P3-F111","claim":"A shot could be fired about every ten minutes (loading about 5–6 minutes).","value":"10","unit":"minutes","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 75–76","quote":"a shot can be fired every ten minutes","conf":"High","conf_note":"Measured in Hansen's trials, no windlass used.","corr":"saimre2006trebuchet","topic":"ST-13; rate-of-fire"},"P3-F155":{"id":"P3-F155","claim":"Raymond reports that the Count's men forced captured Saracens to work, and that the Bishop of Albara was in charge of those bringing in timber.","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"placed the Bishop of Albara in charge of the Saracens and others who brought in the timber","conf":"Medium","conf_note":"Eyewitness report.","corr":"","topic":"ST-19; jerusalem-1099; labor"},"P3-F042":{"id":"P3-F042","claim":"For stone-throwers, the spring diameter in dactyls equals 1.1 times the cube root of 100 times the stone's weight in minas: D = 1.1·∛(100M).","value":"D = 1.1·∛(100M)","unit":"D in dactyls, M in minas","sources":["soedel1979ancient","maguire2024ancient"],"pin":"Soedel & Foley 1979 (page not shown in copy)","quote":"the diameter of the cord bundle in dactyls (about 19.8 millimeters) is equal to 1.1 times the cube root of 100 times the weight of the ball in minas (about 437 grams)","conf":"High","conf_note":"B and C sources agree exactly; consistent with the A source's SI form.","corr":"maguire2024ancient; paasch2024estimation","topic":"ST-06; catapult-design; scaling"},"P3-F227":{"id":"P3-F227","claim":"The boathouse fire happened on Friday 10 April 2015, shortly before 6 pm.","value":"2015-04-10","unit":"date","sources":["leamingtonobserver2015investigation","ihbc2015warwick"],"pin":"Observer para. 2","quote":"ignited the thatched roof of the Victorian boathouse shortly before 6pm on Friday (April 10)","conf":"High","conf_note":"Two independent sources.","corr":"ihbc2015warwick; medievalhistories2015warwick","topic":"ST-29; incident"},"P3-F109":{"id":"P3-F109","claim":"Range increased by about 30 m for every additional 500 kg of ballast.","value":"30 per 500","unit":"m per kg","sources":["hansen1992experimental"],"pin":"section on trials (Fig. 24)","quote":"the range is increased by about 30 m for every additional 500 kg placed in the ballast box","conf":"Medium","conf_note":"Read from Hansen's diagram; partly extrapolated.","corr":"","topic":"ST-13; performance-data"},"P3-F130":{"id":"P3-F130","claim":"In the Nahua account, the stone fell behind the marketplace at Xomolco instead of on the people.","value":"","unit":"","sources":["sahagun1993florentine"],"pin":"Book 12, ch. 38","quote":"But the stone did not land on the people, but fell behind the marketplace at Xomolco.","conf":"Medium","conf_note":"Defenders' account compiled later.","corr":"","topic":"ST-15; failure; nahua-account"},"P3-F030":{"id":"P3-F030","claim":"Fulton concludes the counterweight trebuchet appears to have been introduced by the end of the 12th century.","value":"end of 12th century","unit":"date","sources":["fulton2016artillery"],"pin":"vii","quote":"the counterweight trebuchet appears to have been introduced by the end of the twelfth century","conf":"Medium","conf_note":"Scholarly argument; others (e.g. Chevedden) date it earlier.","corr":"purton2018review","topic":"ST-04; chronology; counterweight-trebuchet"},"P3-F107":{"id":"P3-F107","claim":"The machine was built for 4,000 kg of ballast but had been loaded with only 2,000 kg.","value":"4000; 2000","unit":"kg","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 75–76","quote":"It is built to take a ballast of 4000 kg, but has so far only been loaded with 2000 kg.","conf":"High","conf_note":"Two scholarly sources.","corr":"saimre2006trebuchet","topic":"ST-13; design-parameters"},"P3-F190":{"id":"P3-F190","claim":"The beam was 5.5 m long and the axle 3.1 m high; initial beam angle 44 degrees.","value":"5.5; 3.1; 44","unit":"m; m; degrees","sources":["saimre2006trebuchet"],"pin":"76","quote":"The beam has a length of 5.5 m and the initial angle to horizon is 44 degrees.","conf":"High","conf_note":"Author's own report (axle height was a planning decision).","corr":"","topic":"ST-24; design-parameters"},"P3-F097":{"id":"P3-F097","claim":"The Ayyubid fortifications were intentionally destroyed in 1219 and again in 1220 at al-Muʿaẓẓam's command, and collapsed masonry found at the foot of the forewall and near Herod's Gate bears witness to it.","value":"1219, 1220","unit":"years","sources":["wekslerbdolah2011early"],"pin":"447","quote":"The Ayyubid fortifications were intentionally destroyed in 1219 and again in 1220 at the command of al-Malik al-Muʾaẓẓam ʿIsa.","conf":"High","conf_note":"Historical sources supported by excavated collapse.","corr":"karakas2024issue","topic":"ST-12; jerusalem-1219; archaeology"},"P3-F106":{"id":"P3-F106","claim":"The base followed a ground plan by Villard de Honnecourt (mid-13th century); the rest followed Viollet-le-Duc's 1854 drawings.","value":"13th century; 1854","unit":"","sources":["saimre2006trebuchet"],"pin":"75–76","quote":"The base of the machine was built according to a ground-plan of Villard de Honnecourt dating to the middle of the 13th century.","conf":"High","conf_note":"Scholarly summary of Hansen.","corr":"","topic":"ST-13; design-sources"},"P3-F038":{"id":"P3-F038","claim":"The drawing in al-Ṭarṣūsī's treatise is the first known illustration of the counterweight engine.","value":"","unit":"","sources":["purton2018review"],"pin":"","quote":"The first known illustration of the counterweight engine remains the drawing in the treatise of the Egyptian al-Tarsūsī.","conf":"Medium","conf_note":"Scholarly consensus as summarized in a review; original (Fulton 2018, Cahen 1948) not read.","corr":"","topic":"ST-05; tarsusi; counterweight-origin"},"P3-F160":{"id":"P3-F160","claim":"Hew Kennedy built the trebuchet at Acton Round, near Bridgnorth, Shropshire, with his friend Richard Barr.","value":"Hew Kennedy; Richard Barr","unit":"","sources":["shropshirestar2008county","chevedden1995trebuchet"],"pin":"Star para. 5–6; Chevedden 66–67 (caption)","quote":"The 60-foot-high reconstruction was built in Shropshire by Hew Kennedy and Richard Barr.","conf":"High","conf_note":"Two independent sources name both builders.","corr":"chevedden1995trebuchet","topic":"ST-20; modern-reconstruction"},"P3-F158":{"id":"P3-F158","claim":"Bennett argues the Genoese supplied skilled personnel who understood ropes, pulleys, cranes and cantilevers.","value":"","unit":"","sources":["bennett2013amphibious"],"pin":"134","quote":"for sailors understood the use of ropes and pulleys, cranes and cantilevers","conf":"Medium","conf_note":"Historian's interpretation.","corr":"","topic":"ST-19; jerusalem-1099; crews"},"P3-F126":{"id":"P3-F126","claim":"The supporting structure failed after four shots and the trials were stopped.","value":"4","unit":"shots","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 74–75","quote":"The supporting structure of the machine failed after only four shots and the experiment had to be stopped.","conf":"Medium","conf_note":"Hansen and Saimre (Saimre follows Hansen); Finó does not mention it.","corr":"saimre2006trebuchet","topic":"ST-14; modern-reconstruction"},"P3-F045":{"id":"P3-F045","claim":"Philo of Byzantium described the diameter of the spring hole as the basic unit of measure for building engines, obtained by a standard method valid at all sizes.","value":"","unit":"","sources":["paasch2024estimation"],"pin":"2 (quoting Philo via Marsden 1971)","quote":"the fundamental basis and unit of measure for the construction of engines was the diameter of the hole","conf":"High","conf_note":"Ancient statement seen in a peer-reviewed article's quotation; original translation (Marsden 1971) to fetch.","corr":"","topic":"ST-06; catapult-design; primary-source"},"P3-F150":{"id":"P3-F150","claim":"The Anglo-Norman mangonel is attested from 1155, already alongside perrieres (petraries).","value":"1155","unit":"year AD","sources":["anglonorman2025mangonel","anglonorman2025perriere"],"pin":"s.v. mangonel; s.v. perriere sense 1","quote":"tost ourent fait mangunels As perieres contregeter","conf":"High","conf_note":"Scholarly dictionary.","corr":"","topic":"ST-18; words; anglo-norman"},"P3-F156":{"id":"P3-F156","claim":"Genoese sailors under William Embriaco, though they had lost their ships at Jaffa, saved ropes, mallets, spikes, axes and hatchets and assisted Count Raymond's work on Mount Zion.","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"they bad much assistance from William Embriaco, and the Genoese sailors, who, although they bad lost their ships at Joppa","conf":"Medium","conf_note":"Eyewitness report (Krey's text has OCR 'bad' for 'had').","corr":"bennett2013amphibious","topic":"ST-19; jerusalem-1099; materials"},"P3-F028":{"id":"P3-F028","claim":"A stone from one of King Richard's engines killed twelve men and was carried to Saladin for inspection; Richard had brought it from Messina.","value":"12","unit":"men","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 206)","quote":"a stone sent from one of them killed twelve men with its blow; the stone was afterwards carried to Saladin for inspection","conf":"Low","conf_note":"Anecdote in a pro-Richard chronicle.","corr":"","topic":"ST-03; acre-1191; richard-i; projectiles"},"P3-F171":{"id":"P3-F171","claim":"Francesco Morosini (1619–1694) led the Venetian expedition; Count Otto Wilhelm von Königsmarck commanded the mercenary land forces.","value":"","unit":"","sources":["chatziaslanindmorosini","ehrlich2026athens"],"pin":"","quote":"Francesco Morosini (1619-1694) was appointed as its leader.","conf":"High","conf_note":"Two B sources agree on Morosini as commander in chief and Königsmarck as field commander.","corr":"ehrlich2026athens","topic":"ST-22; athens-1687; commanders"},"P3-F214":{"id":"P3-F214","claim":"The Colossus was built c. 294–282 BC and toppled by an earthquake about 226/225 BC; Pliny says it fell 56 years after it was erected.","value":"c. 294–282 BC","unit":"dates","sources":["britannica2026colossus","pliny1855natural"],"pin":"Pliny 34.41","quote":"took 12 years to build (c. 294–282 BCE)","conf":"High","conf_note":"Reference work plus ancient report agree.","corr":"pliny1855natural","topic":"ST-27; colossus; chronology"},"P3-F237":{"id":"P3-F237","claim":"Yankee Siege was designed to throw objects of up to 300 lb.","value":"300","unit":"lb","sources":["nhbr2004pumpkin","npr2005pumpkin"],"pin":"NHBR para. 10; NPR photo caption","quote":"The Yankee Siege was designed to throw objects as heavy as 300 pounds.","conf":"Medium","conf_note":"Builders' claim reported by two independent outlets.","corr":"npr2005pumpkin","topic":"ST-30; modern-record"},"P3-F064":{"id":"P3-F064","claim":"About 30 American and 15 European timber framers took part.","value":"30; 15","unit":"people","sources":["schupp1998timber"],"pin":"para. 1","quote":"to join 30 other timber framers and another 15 of their European counterparts","conf":"Medium","conf_note":"Single newspaper; Hadingham says 'more than 50 craftsmen'.","corr":"hadingham2000ready","topic":"ST-08; crews"},"P3-F213":{"id":"P3-F213","claim":"Pliny says the Colossus took twelve years and 300 talents, raised from the engines Demetrius abandoned; it was 70 cubits tall.","value":"300","unit":"talents","sources":["pliny1855natural"],"pin":"34.41","quote":"It is said that it was twelve years before this statue was completed, and that three hundred talents were expended upon it","conf":"Medium","conf_note":"Pliny reports hearsay ('it is said'); 12-year build corroborated by Britannica (c. 294–282 BC).","corr":"britannica2026colossus; higgins2024alternative; marino2018rise","topic":"ST-27; rhodes-305; colossus"},"P3-F115":{"id":"P3-F115","claim":"In 1850 President Louis-Napoléon Bonaparte ordered a trebuchet to be rebuilt and tested at the Vincennes range.","value":"1850","unit":"year","sources":["fino1972machines"],"pin":"34–35","quote":"En 1850, sur l'ordre du Président Louis-Napoléon Bonaparte, on reconstruisit un trébuchet que l'on essaya au polygone de Vincennes.","conf":"High","conf_note":"Scholarly source citing the original report; Hansen and Saimre confirm the Vincennes trial (without date).","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; modern-reconstruction"},"P3-F165":{"id":"P3-F165","claim":"Kennedy threw upright and grand pianos and dead farm animals.","value":"","unit":"","sources":["hadingham2000ready","lienhardndmodern","shropshirestar2008county"],"pin":"Hadingham para. on Kennedy","quote":"hurling drums of flaming gasoline, upright and grand pianos, dead farm animals, even a one-ton car","conf":"High","conf_note":"Three independent sources (the Star says dead cattle).","corr":"lienhardndmodern; shropshirestar2008county","topic":"ST-20; modern-reconstruction"},"P3-F009":{"id":"P3-F009","claim":"A concentration of 79 ballista stones was found in situ west of the Third Wall at the Russian Compound, in an area of 15.0 × 5.2 m.","value":"79","unit":"stones","sources":["arbiv2023evidence"],"pin":"109","quote":"To the west of the wall, outside the city, a concentration of 79 ballista stones was found in situ in a rather small area (L232, L236, L253; 15.0 × 5.2 m","conf":"High","conf_note":"Excavated and published assemblage.","corr":"","topic":"ST-01; jerusalem-70; archaeology"},"P3-F025":{"id":"P3-F025","claim":"The Duke of Burgundy, the Templars and the Hospitallers each had their own petraria.","value":"3","unit":"engines","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"On one side, the petraria of the duke of Burgundy plied; on the other, that of the Templars did severe execution; while that of the Hospitallers never ceased to cast terror amongst the Turks.","conf":"Medium","conf_note":"Chronicle report.","corr":"","topic":"ST-03; acre-1191; military-orders"},"P3-F132":{"id":"P3-F132","claim":"Cortés wrote that he concealed the machine's defects by pretending that compassion stopped him from using it.","value":"","unit":"","sources":["cortes2004catapult"],"pin":"third letter (Cartas y relaciones, 319-21)","quote":"we concealed from them the defects of the machine","conf":"Medium","conf_note":"Self-serving letter; translator unidentified.","corr":"","topic":"ST-15; cortes; source-criticism"},"P3-F147":{"id":"P3-F147","claim":"English mangonel comes via Middle English and Anglo-French mangunel from Medieval Latin manganum and Greek mánganon; first known use 13th century.","value":"13th century","unit":"first known use","sources":["merriamwebster2026mangonel"],"pin":"Etymology; First Known Use","quote":"","conf":"High","conf_note":"Reference dictionary.","corr":"etymonline2026trebuchet","topic":"ST-18; words; etymology"},"P3-F146":{"id":"P3-F146","claim":"Greek mánganon first meant a love charm and later a military engine and other mechanical devices.","value":"","unit":"","sources":["merriamwebster2026mangonel"],"pin":"Etymology","quote":"","conf":"High","conf_note":"Reference dictionary; Etymonline agrees on the 'tricking or bewitching' sense.","corr":"etymonline2026trebuchet","topic":"ST-18; words; etymology"},"P3-F061":{"id":"P3-F061","claim":"Stirling Castle surrendered on St Margaret's Day, 20 July 1304.","value":"20 July 1304","unit":"date","sources":["rcahms1963stirlingshire"],"pin":"p. 181","quote":"In the end the Castle surrendered on St. Margaret's Day, 20th July 1304.","conf":"High","conf_note":"Heritage inventory.","corr":"","topic":"ST-07; stirling-1304; dating"},"P3-F131":{"id":"P3-F131","claim":"The Mexica called the machine a 'wooden sling'.","value":"","unit":"","sources":["sahagun1993florentine"],"pin":"Book 12, ch. 38","quote":"Then because of that they named it a 'wooden sling.'","conf":"High","conf_note":"Scholarly translation of the Nahuatl.","corr":"","topic":"ST-15; words; nahuatl"},"P3-F215":{"id":"P3-F215","claim":"Some of the abandoned siege materials were probably recycled into the statue and the rest sold to pay for it.","value":"","unit":"","sources":["higgins2024alternative","marino2018rise"],"pin":"","quote":"Some of these materials must have been recycled for the construction of the statue and the rest was sold to pay for the project.","conf":"Medium","conf_note":"Modern inference from ancient testimony; NatGeo agrees.","corr":"marino2018rise","topic":"ST-27; colossus; materials"},"P3-F069":{"id":"P3-F069","claim":"Both machines eventually hit the wall; the fixed machine's hit broke through to the back and Beffeyte's shot left it bulging and cracked.","value":"","unit":"","sources":["nova2000secrets","schupp1998timber"],"pin":"transcript, final sequence","quote":"And it's busted it right through to the back.","conf":"High","conf_note":"Documentary; participant: 'It really smashed that wall.'","corr":"schupp1998timber","topic":"ST-08; wall-target"},"P3-F203":{"id":"P3-F203","claim":"The Mongols besieged Xiangyang for five years, 1268-73, and its commander surrendered in 1273.","value":"1268-1273","unit":"years AD","sources":["britannica2026xiangyang"],"pin":"Xiangyang entry","quote":"Mongols besieged it for five years (1268–73). The Chinese commander finally surrendered in 1273","conf":"High","conf_note":"Reference-work dating; consistent with Hanson and Wuyungaowa.","corr":"wuyungaowa2012mongol; hanson2004mongol","topic":"ST-26; xiangyang-1273; dating"},"P3-F098":{"id":"P3-F098","claim":"Under the 1229 settlement with Frederick II the already destroyed walls were not rebuilt.","value":"1229","unit":"year","sources":["britannica2026crusades"],"pin":"section 'The Crusade of Frederick II'","quote":"The walls of Jerusalem, which had already been destroyed, were not rebuilt, and the peace was to last for 10 years.","conf":"High","conf_note":"Reference work; Karakaş also says the crusaders observed the treaty and did not fortify the city.","corr":"karakas2024issue","topic":"ST-12; jerusalem-1229"},"P3-F232":{"id":"P3-F232","claim":"The old machine was retired because wear and tear made it unsafe.","value":"","unit":"","sources":["smith2022warwick","mingins2023warwick"],"pin":"Bartlett quote","quote":"the wear and tear got to the point where it was no longer safe to operate","conf":"High","conf_note":"Castle statement in two papers.","corr":"mingins2023warwick","topic":"ST-29; maintenance"},"P3-F229":{"id":"P3-F229","claim":"The trebuchet had been fired some 6,500 times by April 2015.","value":"6500","unit":"firings","sources":["leamingtonobserver2015investigation","ihbc2015warwick"],"pin":"Observer para. 7","quote":"has been fired some 6,500 times","conf":"Medium","conf_note":"Castle figure via two outlets ('at least 6,500' in BBC/IHBC).","corr":"ihbc2015warwick","topic":"ST-29; usage"},"P3-F154":{"id":"P3-F154","claim":"Raymond reports that 50–60 men carried on their shoulders a beam that four pairs of oxen could not have dragged.","value":"50–60","unit":"men","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"fifty or sixty men carried on their shoulders a great beam that could not have been dragged by four pair of oxen","conf":"Low","conf_note":"Reported, likely rhetorical; no measurement.","corr":"","topic":"ST-19; jerusalem-1099; materials"},"P3-F022":{"id":"P3-F022","claim":"The French king had a petraria of superior quality named 'Bad Neighbour'.","value":"Bad Neighbour","unit":"","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"he had one of superior quality, to which they gave the name of \"Bad Neighbour.\"","conf":"Medium","conf_note":"Reported by a crusader chronicle; name likely genuine.","corr":"","topic":"ST-03; acre-1191; named-engines"},"P3-F016":{"id":"P3-F016","claim":"According to al-Qāḍī al-Fāḍil (via Dajani-Shakeel), the mangonels' fire destroyed the tops of the towers, letting the sappers work.","value":"","unit":"","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"the fire from the mangonels destroyed thc tops of the towers","conf":"Medium","conf_note":"Chronicle report via modern scholar (OCR 'thc' for 'the').","corr":"brundage1962expugnatione","topic":"ST-02; jerusalem-1187; artillery"},"P3-F052":{"id":"P3-F052","claim":"Polybius's Greek calls Archimedes' long-range stone-throwers lithoboloi (λιθοβόλοις), which Paton's 1923 Loeb anachronistically translates 'mangonels'.","value":"λιθοβόλος","unit":"","sources":["polybius1923histories"],"pin":"8.5.2","quote":"with his more powerful mangonels and heavier missiles","conf":"High","conf_note":"Greek checked on Perseids (perseus-grc2).","corr":"","topic":"ST-06; terminology"},"P3-F125":{"id":"P3-F125","claim":"The counterweight drop height was only about half a meter.","value":"0.5","unit":"m","sources":["saimre2006trebuchet"],"pin":"74–75","quote":"the drop height of the counterweight was just around half a metre","conf":"Medium","conf_note":"Saimre's calculation from the reported geometry.","corr":"","topic":"ST-14; design-parameters"},"P3-F039":{"id":"P3-F039","claim":"Fulton judges the design immature compared with the other engines al-Ṭarṣūsī drew.","value":"","unit":"","sources":["purton2018review"],"pin":"Purton quoting Fulton 2018, 434","quote":"he acknowledges 'the immaturity of the design is clear' (434), unlike the other engines he drew","conf":"Medium","conf_note":"Quoted in a review.","corr":"","topic":"ST-05; tarsusi"},"P3-F196":{"id":"P3-F196","claim":"Lihula (1997): 600 kg counterweight threw an 8 kg stone 100 m (first shot 300 kg / 5 kg / about 40 m).","value":"100","unit":"m","sources":["saimre2006trebuchet"],"pin":"75","quote":"The second shot used a 600 kg counterweight and hurled an 8 kg stone to a distance of 100 m.","conf":"Medium","conf_note":"Published trial shots reported second-hand by Saimre.","corr":"","topic":"ST-24; performance-data"},"P3-F230":{"id":"P3-F230","claim":"The boathouse dated from 1896.","value":"1896","unit":"year","sources":["leamingtonobserver2015investigation","ihbc2015warwick","medievalhistories2015warwick"],"pin":"Observer penultimate para.","quote":"The boathouse, which was undergoing restoration, dates back to 1896.","conf":"High","conf_note":"Three sources (one other says 1895).","corr":"ihbc2015warwick; medievalhistories2015warwick","topic":"ST-29; incident"},"P3-F206":{"id":"P3-F206","claim":"Fancheng fell in the first month of 1273 to the Huihui pao, which were then moved against Xiangyang, which fell in the second month.","value":"1273","unit":"year AD","sources":["wuyungaowa2012mongol"],"pin":"text","quote":"1273年正月蒙古军，使用回回炮攻下樊城。然后，将回回炮移到襄阳。2月攻破襄阳","conf":"Medium","conf_note":"Specialist summary of Chinese sources; lunar months.","corr":"hanson2004mongol","topic":"ST-26; xiangyang-1273; outcome"},"P3-F189":{"id":"P3-F189","claim":"It was built of spruce logs with present-day tools in six days of three to four hours' work each.","value":"6; 3–4","unit":"days; hours/day","sources":["saimre2006trebuchet"],"pin":"76","quote":"Construction work took six days, only up to three or four hours of work was done each day.","conf":"High","conf_note":"Author's own report.","corr":"","topic":"ST-24; modern-reconstruction"},"P3-F013":{"id":"P3-F013","claim":"After one week (Ernoul) or five days (Arab chroniclers) Saladin moved his camp to the north-eastern corner of the city.","value":"5–7","unit":"days","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"his troops camped in a triangular area at the northeastern corner of the city","conf":"Medium","conf_note":"De expugnatione independently describes a move of camp (dated 26 September) to the Vale of Jehoshaphat and Mount of Olives.","corr":"brundage1962expugnatione","topic":"ST-02; jerusalem-1187"},"P3-F010":{"id":"P3-F010","claim":"Most of the 79 stones weigh less than 11 kg and none exceeds 20 cm in diameter; one weighs about 24 kg.","value":"24","unit":"kg","sources":["arbiv2023evidence"],"pin":"109, 114–15","quote":"only one of the 79 ballista stones weighs close to this, about 24 kg, while most of them weigh less than 11 kg and their diameter does not exceed 20 cm","conf":"High","conf_note":"Measured weights reported by the excavator.","corr":"","topic":"ST-01; jerusalem-70; archaeology"},"P3-F048":{"id":"P3-F048","claim":"The four surviving ancient artillery manuals are by Biton, Philon of Byzantium (280–220 BC), Vitruvius and Heron of Alexandria; doubling a machine's capacity required the cube root of two (the Delian problem), which Philon attacked through two mean proportionals.","value":"∛2","unit":"","sources":["maguire2024ancient"],"pin":"","quote":"By Philon's time it was appreciated that a good way of attacking the cube root problem was through the theorem of two mean proportionals.","conf":"Medium","conf_note":"Tier C source; consistent with Soedel & Foley's list of 'cube-root investigators' (Philo, Archimedes, Hero).","corr":"soedel1979ancient","topic":"ST-06; catapult-design; mathematics"},"P3-F023":{"id":"P3-F023","claim":"The Turkish defenders had an engine called 'Bad Kinsman' that often broke 'Bad Neighbour' in pieces.","value":"Bad Kinsman","unit":"","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"The Turks also had one they called \"Bad Kinsman,\" which by its violent casts, often broke \"Bad Neighbour\" in pieces","conf":"Medium","conf_note":"Chronicle report.","corr":"","topic":"ST-03; acre-1191; counter-battery"},"P3-F096":{"id":"P3-F096","claim":"During the Fifth Crusade (1217–1221) al-Muʿaẓẓam, fearing crusader capture of Jerusalem, had all the city walls except the Tower of David (inner citadel) demolished.","value":"","unit":"","sources":["karakas2024issue"],"pin":"69–70","quote":"el-Muazzam, V. Haçlı Seferi sırasında (1217-1221) Haçlıların Kudüs'ü ele geçirmesinden endişe edip Dâvud Burcu (iç kale) haricinde kalan Kudüs surlarını tamamen yıktırmıştı","conf":"Medium","conf_note":"Peer-reviewed article citing Arabic chroniclers; Turkish original, our translation.","corr":"wekslerbdolah2011early","topic":"ST-12; jerusalem-1219"},"P3-F185":{"id":"P3-F185","claim":"Textual evidence suggests de' Mussi did not travel to Caffa.","value":"","unit":"","sources":["wheelis2002biological"],"pin":"971-975","quote":"While this does not rule out travel to Caffa in late 1346, textual evidence suggests that he did not.","conf":"High","conf_note":"Peer-reviewed argument.","corr":"","topic":"ST-23; source-criticism"},"P3-F239":{"id":"P3-F239","claim":"Yankee Siege II threw pumpkins more than half a mile; AIAA gives its trebuchet record as 2,835.81 ft (864 m).","value":"2835.81","unit":"ft","sources":["hyland2014pumpkin","ap2016pumpkins"],"pin":"AIAA records para.; AP para. on Yankee Siege II","quote":"an 8-time world champion pumpkin launcher sending pumpkins more than a half mile","conf":"Medium","conf_note":"The exact figure is from AIAA (2014) only; AP (2016) corroborates 'more than a half mile' (over 805 m). Year of the record not stated.","corr":"ap2016pumpkins","topic":"ST-30; modern-record"},"P3-F073":{"id":"P3-F073","claim":"Raymond reports stones hurled from every side from tormenti and petrahae (Latin terms kept by Krey).","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"From every side stones were hurled from the tormenti and the petrahae, and so many arrows that they fell like hail","conf":"Medium","conf_note":"Eyewitness; engine types not specified further.","corr":"","topic":"ST-09; jerusalem-1099; artillery; terms"},"P3-F212":{"id":"P3-F212","claim":"Under the peace terms Rhodes stayed autonomous and ungarrisoned, and became an ally of Antigonus except against Ptolemy.","value":"","unit":"","sources":["diodorus1954library"],"pin":"20.99.3","quote":"the city should be autonomous and ungarrisoned and should enjoy its own revenue","conf":"Medium","conf_note":"Ancient report.","corr":"","topic":"ST-27; rhodes-305"},"P3-F076":{"id":"P3-F076","claim":"Raymond says the crusader machines were being shaken apart by many stones.","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"Our machines were now shaken apart by the blows of many stones","conf":"Medium","conf_note":"Eyewitness.","corr":"","topic":"ST-09; jerusalem-1099; artillery"},"P3-F041":{"id":"P3-F041","claim":"For arrow-shooters, the diameter of the torsion spring (cord bundle) was set at one-ninth of the arrow length.","value":"1/9","unit":"of arrow length","sources":["soedel1979ancient","maguire2024ancient","paasch2024estimation"],"pin":"Soedel & Foley 1979; Paasch & Paasch 2024, 3 (eq. 2)","quote":"For the arrow shooter the diameter of the cord bundle was set simply as 1/9 of the arrow length.","conf":"High","conf_note":"Three independent modern sources agree (all ultimately based on Philo, Heron and Vitruvius via Marsden).","corr":"maguire2024ancient; paasch2024estimation","topic":"ST-06; catapult-design; scaling"},"P3-F058":{"id":"P3-F058","claim":"The royal records call the engine 'le Lup de guerre' and Langtoft calls it 'Ludgar'.","value":"","unit":"","sources":["rcahms1963stirlingshire","anglonorman2025ludgar"],"pin":"RCAHMS p. 181 n. 4; AND s.v. ludgar","quote":"\"le Lup de guerre\"; cf. Langtoft's \"Ludgar\"","conf":"High","conf_note":"Two scholarly sources agree.","corr":"","topic":"ST-07; words; warwolf"},"P3-F071":{"id":"P3-F071","claim":"Raymond says the defenders, seeing the many crusader machines, strengthened the weaker parts of the wall.","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"strengthened the weaker parts of the wall, so that it seemed that they could be taken only by the most desperate efforts","conf":"Medium","conf_note":"Eyewitness; the Gesta independently reports defenders heightening towers.","corr":"krey1921gesta","topic":"ST-09; jerusalem-1099; defense"},"P3-F090":{"id":"P3-F090","claim":"Josephus says the engines' stones carried away the pinnacles of the wall and broke off the corners of towers.","value":"","unit":"","sources":["josephus1895war"],"pin":"3.243","quote":"they carried away the pinnacles of the wall, and broke off the corners of the towers","conf":"Medium","conf_note":"Reported by the defending commander.","corr":"","topic":"ST-11; jotapata-67; artillery-effects"},"P3-F113":{"id":"P3-F113","claim":"A medium-sized machine built by the Museum of Falsters Minder grouped its shots within a 6 m square at 180 m.","value":"6; 180","unit":"m; m","sources":["chevedden1995trebuchet"],"pin":"69","quote":"A machine of medium size built by the Museum of Falsters Minder in Denmark has proved capable of grouping its shots, at a range of 180 meters, within a six-meter square.","conf":"Medium","conf_note":"Reported without details; does not match Hansen's 168 m maximum.","corr":"","topic":"ST-13; accuracy"},"P3-F114":{"id":"P3-F114","claim":"(Extra, for Ch. 6) Saimre measured the long arm 5.85 m, short arm 1.2 m, axle height 3.15 m from Hansen's blueprint and calculated a theoretical maximum of 490 m (efficiency 0.34).","value":"5.85; 1.2; 3.15; 490; 0.34","unit":"m; m; m; m; ratio","sources":["saimre2006trebuchet"],"pin":"75–76","quote":"Theoretical maximum range of a 15 kg missile and 2000 kg counterweight with this machine is 490 m.","conf":"Medium","conf_note":"Derived by Saimre; not in retelling.","corr":"","topic":"ST-13; phase6-data"},"P3-F104":{"id":"P3-F104","claim":"The team included a smith, a millwright and a rigger.","value":"","unit":"","sources":["saimre2006trebuchet","hansen1992experimental"],"pin":"Saimre 75–76","quote":"Among the team there were a smith, millwright and a rigger","conf":"High","conf_note":"Saimre summarizing Hansen; Hansen's copy also lists a historian, architect, archaeologist and engineer.","corr":"hansen1992experimental","topic":"ST-13; crews"},"P3-F139":{"id":"P3-F139","claim":"Abu'l-Fida described an engine used at the final capture of Acre, entrusted to the troops of Hamah, which formed a load for 100 carts, one of them in his charge.","value":"100","unit":"carts","sources":["yule1903book"],"pin":"vol. 2, p. 209 (DSR copy)","quote":"which formed a load for 100 carts, of which one was in charge of the historian himself","conf":"Medium","conf_note":"Participant's report relayed by a scholarly editor.","corr":"zaimeche2005hama; cartwright2018siege","topic":"ST-17; acre-1291; logistics"},"P3-F151":{"id":"P3-F151","claim":"McCotter, following Bradbury, warns against being dogmatic about weapon types based only on the word used in western sources.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text","quote":"Bradbury has shown the danger of trying to be dogmatic about weapon types based purely on the word given to them in western sources","conf":"High","conf_note":"Scholarly caution.","corr":"","topic":"ST-18; source-criticism"},"P3-F184":{"id":"P3-F184","claim":"Wheelis notes the machines were technically trebuchets, not catapults.","value":"","unit":"","sources":["wheelis2002biological"],"pin":"n. 1","quote":"Technically trebuchets, not catapults.","conf":"High","conf_note":"Accurate report of the author's footnote.","corr":"","topic":"ST-23; words; terminology"},"P3-F173":{"id":"P3-F173","claim":"On 22 September a deserter reportedly told the Venetians that all the ammunition had been moved into the Parthenon, where the Ottoman dignitaries had also taken refuge.","value":"22 September 1687","unit":"date","sources":["chatziaslanindmorosini"],"pin":"","quote":"an escapee from the Fortress informed the Venetians that all of the ammunition had been transferred to the so-called Temple of Athena","conf":"Medium","conf_note":"From the testimony of a German officer (Sobievolski) cited by the author.","corr":"","topic":"ST-22; athens-1687; intelligence"},"P3-F231":{"id":"P3-F231","claim":"A £500,000 replacement to the same specifications was built by Carpenter Oak, the original builders, for spring 2023.","value":"500000; 2023","unit":"GBP; year","sources":["smith2022warwick","mingins2023warwick"],"pin":"Smith paras. 3, 7–8; Mingins para. 1–2","quote":"Warwick Castle has appointed Carpenter Oak to undertake the rebuild.","conf":"High","conf_note":"Two independent local papers.","corr":"mingins2023warwick","topic":"ST-29; modern-reconstruction"},"P3-F080":{"id":"P3-F080","claim":"Appian reports that Sulla cut down the grove of the Academy and built his largest engines there.","value":"","unit":"","sources":["appian1899mithridatic"],"pin":"Mith. 30","quote":"Sulla chopped down the grove of the Academy and constructed his largest engines there.","conf":"Medium","conf_note":"Reported by Appian; Plutarch independently reports the ravaging of the Academy.","corr":"plutarch1916sulla","topic":"ST-10; athens-86-siege; timber"},"P3-F094":{"id":"P3-F094","claim":"Yodefat was excavated over six seasons from 1992, and archaeology confirmed a heavy battle along the lines Josephus describes.","value":"1992","unit":"first excavation season","sources":["strauss2022siege"],"pin":"","quote":"Archaeology confirmed a heavy battle along the lines described by Josephus, with the consequent murder and ruin.","conf":"High","conf_note":"Expert secondary summary; excavation report (Aviam 2002) to fetch for artillery finds.","corr":"","topic":"ST-11; jotapata-67; archaeology"},"P3-F142":{"id":"P3-F142","claim":"Abu'l-Fida, as an emir of ten, had charge of only one wagon-load of the dismantled engine.","value":"1","unit":"wagon","sources":["zaimeche2005hama","yule1903book"],"pin":"Zaimeche n. 159; Yule 2:209","quote":"The part consigned to me was only one wagon load, since at the time I was an Emir of ten.","conf":"Medium","conf_note":"Participant's report.","corr":"","topic":"ST-17; acre-1291; eyewitness"},"P3-F169":{"id":"P3-F169","claim":"Campbell concludes that lead bullets were not intended to be shot from catapults and that Sulla's use at the Piraeus reflects the general's ingenuity rather than an artillery tradition.","value":"","unit":"","sources":["campbell2011ancient"],"pin":"698","quote":"Sulla's gambit at Piraeus can be put down to the general's ingenuity, rather than to any long-standing artillery tradition.","conf":"High","conf_note":"Scholarly interpretation in a peer-reviewed article (it is an opinion, reliably reported).","corr":"","topic":"ST-21; catapults; sling-bullets; historiography"},"P3-F072":{"id":"P3-F072","claim":"The Gesta says the defenders greatly strengthened the fortifications and increased the height of the turrets at night.","value":"","unit":"","sources":["krey1921gesta"],"pin":"Krey 1921 (Fordham web text, Gesta 'The Fall of Jerusalem')","quote":"they greatly strengthened the fortifications of the city and increased the height of the turrets at night","conf":"Medium","conf_note":"Eyewitness.","corr":"raymond1921historia","topic":"ST-09; jerusalem-1099; defense"},"P3-F234":{"id":"P3-F234","claim":"The machine was 50–55 ft tall on 10 ft iron wheels.","value":"50–55 (15–17); 10 (3)","unit":"ft (m)","sources":["nhbr2004pumpkin","pratt2008pumpkin"],"pin":"NHBR para. 9; Pratt","quote":"It is 50 feet high and rides on four 10-foot iron wheels.","conf":"High","conf_note":"Two sources; height differs by 5 ft.","corr":"pratt2008pumpkin","topic":"ST-30; design-parameters"},"P3-F133":{"id":"P3-F133","claim":"McCotter dates the Avar-Slav siege of Thessalonica to 586, following Lemerle, while some scholars put it at 597.","value":"586","unit":"year AD","sources":["mccotter2003byzantines"],"pin":"text and n. 19","quote":"While some scholars put it at 597, I prefer the date of 586, as advocated by Lemerle.","conf":"Medium","conf_note":"Date disputed in scholarship.","corr":"","topic":"ST-16; thessalonica-586; dating"},"P3-F141":{"id":"P3-F141","claim":"Rain and snow struck the column between Ḥiṣn al-Akrād and Damascus, and the journey took a month instead of the usual eight days.","value":"1","unit":"month","sources":["zaimeche2005hama","cartwright2018siege"],"pin":"Zaimeche n. 159; Cartwright text","quote":"It took us a month to reach Acre, usually an eight day ride.","conf":"Medium","conf_note":"Participant's report via two C sources (Cartwright gives a month; Zaimeche adds eight days).","corr":"","topic":"ST-17; acre-1291; logistics; weather"},"P3-F056":{"id":"P3-F056","claim":"Carts of lead came to Stirling from Brechin (5), Dunfermline (12) and St Andrews (22).","value":"5 / 12 / 22","unit":"carts","sources":["macivor2024war"],"pin":"blog text","quote":"five carts from Brechin, 12 from Dunfermline and 22 from St Andrews arrived at the castle filled with lead","conf":"Medium","conf_note":"Heritage body (B) but no reference given in the blog.","corr":"","topic":"ST-07; counterweight; lead; logistics"},"P3-F055":{"id":"P3-F055","claim":"Edward ordered the Prince of Wales to provide lead for the weights of his siege engines by stripping roofs, sparing church roofs immediately above the altars.","value":"","unit":"","sources":["rcahms1963stirlingshire"],"pin":"p. 180, n. 14 (Stevenson, Documents ii, 475, 481)","quote":"he ordered the Prince of Wales to provide lead for the weights of his siege-engines by stripping it from roofs","conf":"High","conf_note":"Documentary record; corroborated by HES.","corr":"macivor2024war","topic":"ST-07; counterweight; lead; materials"},"P3-F163":{"id":"P3-F163","claim":"It threw a compact car of 476 kg (engine removed) 80 m using a 30-ton counterweight.","value":"476; 80; 30","unit":"kg; m; ton","sources":["chevedden1995trebuchet"],"pin":"69","quote":"A modern reconstruction made in England has tossed a compact car (476 kilograms without its engine) 80 meters using a 30-ton counterweight.","conf":"Medium","conf_note":"Reported by Chevedden et al., not their own measurement; Hadingham says 'a one-ton car'.","corr":"","topic":"ST-20; performance-data"},"P3-F020":{"id":"P3-F020","claim":"Balian threatened that the Latins would burn their houses, destroy the Dome of the Rock and kill all Muslim prisoners, estimated in the thousands.","value":"","unit":"","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"They would burn their houses, destroy the Dome of the Rock, uproot the Rock, and kill all Muslim prisoners, who were estimated to number in the thousands","conf":"Medium","conf_note":"Chronicle not named in the web text (usually Ibn al-Athīr); confirm in Richards's translation.","corr":"","topic":"ST-02; jerusalem-1187"},"P3-F007":{"id":"P3-F007","claim":"Watchmen on the towers warned when an engine was loosed by crying 'The son cometh' in their own language, and people in the path threw themselves down.","value":"","unit":"","sources":["josephus1895war"],"pin":"5.272","quote":"cried out aloud, in their own country language, 'The son cometh:'","conf":"Medium","conf_note":"The cry's wording is a known textual crux (son/stone); see caveats.","corr":"josephus1737war","topic":"ST-01; jerusalem-70; words"},"P3-F037":{"id":"P3-F037","claim":"Fulton dates the treatise to 1180; it certainly precedes Saladin's death in 1193, to whom it was dedicated.","value":"1180","unit":"year","sources":["purton2018review"],"pin":"","quote":"Fulton dates it to 1180, it certainly precedes the death of Saladin (1193) to whom it was dedicated.","conf":"Medium","conf_note":"Reviewer reporting Fulton's dating.","corr":"zaky1965preliminary","topic":"ST-05; tarsusi; counterweight-origin"},"P3-F051":{"id":"P3-F051","claim":"At Syracuse (213 BC), Polybius says Archimedes' 'stones not less than ten talents' were dropped onto Roman sambucae from swinging beams via pulleys, whereas Plutarch later says a ten-talent stone was 'discharged' at the sambuca.","value":"10","unit":"talents (about 260 kg)","sources":["polybius1923histories","plutarch1917marcellus"],"pin":"Polybius 8.5.8–10; Plutarch, Marcellus 15.3–4","quote":"some of them carrying stones weighing as much as ten talents and others large lumps of lead","conf":"Medium","conf_note":"Polybius is earlier and closer to eyewitnesses; Plutarch's version looks like a later dramatization of dropped weights as thrown missiles. 213 BC is conventional dating, not checked here.","corr":"","topic":"ST-06; archimedes; reported-vs-plausible"},"P3-F123":{"id":"P3-F123","claim":"Shells of 27 cm and 32 cm diameter were thrown 120 m.","value":"120","unit":"m","sources":["fino1972machines","saimre2006trebuchet","hansen1992experimental"],"pin":"Finó 34–35; Saimre 74–75","quote":"des bombes de 0,27 m. et de 0,32 m. à 120 m.","conf":"High","conf_note":"As above.","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; performance-data"},"P3-F062":{"id":"P3-F062","claim":"Five master carpenters and 50 workmen assembled War Wolf.","value":"5 + 50","unit":"workers","sources":["macivor2024war"],"pin":"blog text","quote":"Five master carpenters and 50 workmen had been tirelessly assembling massive wooden beams, winches and an enormous counterweight","conf":"Medium","conf_note":"Heritage-body blog without references; plausible from wardrobe accounts but unchecked.","corr":"","topic":"ST-07; crews; construction"},"P3-F086":{"id":"P3-F086","claim":"Sulla's siege of the Piraeus is dated to 86 BC.","value":"86 BC","unit":"year","sources":["campbell2011ancient"],"pin":"697","quote":"during Sulla's siege of Piraeus in 86 b.c.","conf":"High","conf_note":"Peer-reviewed modern scholarship.","corr":"","topic":"ST-10; athens-86-siege; chronology"},"P3-F019":{"id":"P3-F019","claim":"No one in the city would keep watch on the defenses for a night, even for 100 besants.","value":"100","unit":"besants","sources":["brundage1962expugnatione"],"pin":"Brundage 1962, 159–63 (Fordham web text)","quote":"No man could be found in the whole city who was brave enough to dare keep watch at the defences for a night, even for a fee of a hundred besants.","conf":"Medium","conf_note":"Eyewitness; Dajani-Shakeel quotes the same passage.","corr":"dajanishakeel1988medieval","topic":"ST-02; jerusalem-1187"},"P3-F049":{"id":"P3-F049","claim":"Derived: by the formula, a one-talent stone (about 26 kg) needs a spring about 20 dactyls (about 0.39 m) across, and a three-talent stone (about 78 kg) about 29 dactyls (about 0.56 m).","value":"0.39; 0.56","unit":"m","sources":["soedel1979ancient","paasch2024estimation"],"pin":"","quote":"","conf":"High","conf_note":"Our arithmetic from the sourced formula (talent mass from Soedel & Foley's 78 kg for three talents); not a sourced statement.","corr":"","topic":"ST-06; catapult-design; scaling"},"P3-F060":{"id":"P3-F060","claim":"Langtoft, who was not present, wrote that Ludgar broke down the entire wall at its stroke.","value":"","unit":"","sources":["rcahms1963stirlingshire"],"pin":"pp. 180-181","quote":"And this at its stroke broke down the entire wall.","conf":"Low","conf_note":"Chronicler not present; likely exaggeration.","corr":"","topic":"ST-07; wall-damage"},"P3-F116":{"id":"P3-F116","claim":"Captain Favé conducted the experiments.","value":"Favé","unit":"","sources":["fino1972machines","hansen1992experimental","saimre2006trebuchet"],"pin":"Finó 34–35; Saimre 74–75","quote":"Le Capitaine I. Favé, chargé de conduire les expériences","conf":"High","conf_note":"All three sources agree.","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; modern-reconstruction"},"P3-F143":{"id":"P3-F143","claim":"Al-Maqrizi reported 92 Muslim engines at Acre in 1291, Abulfaraj 300 and a Frankish account 666 of great and small.","value":"92 / 300 / 666","unit":"engines","sources":["yule1903book"],"pin":"vol. 2, p. 209","quote":"the Saracens, according to Makrizi, set 92 engines in battery against the city, whilst Abulfaraj says 300, and a Frank account, of great and small, 666","conf":"Low","conf_note":"Reported numbers that disagree wildly.","corr":"","topic":"ST-17; acre-1291; engine-numbers"},"P3-F145":{"id":"P3-F145","claim":"The most technical term in many early medieval siege descriptions is manganon/mechanis or machinis.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text","quote":"the most technical term used is normally manganon/mechanis or machinis","conf":"High","conf_note":"Scholarly observation.","corr":"","topic":"ST-18; terminology; source-criticism"},"P3-F194":{"id":"P3-F194","claim":"Corrected for height, Saimre estimated an efficiency of about 0.5.","value":"0.5","unit":"ratio","sources":["saimre2006trebuchet"],"pin":"76","quote":"Such a range gives us an efficiency of 0.5, which is quite good.","conf":"Medium","conf_note":"Derived figure using Saimre's own definition and a crude height correction (120 − 35 = 85 m).","corr":"","topic":"ST-24; phase6-data"},"P3-F033":{"id":"P3-F033","claim":"Purton finds it questionable that bombardment with carved stones over 100 kg had no serious physical impact.","value":"100","unit":"kg","sources":["purton2018review"],"pin":"review","quote":"the thought that a bombardment of carefully carved stones weighing more than 100 kilograms would have no serious physical impact on the target remains questionable","conf":"High","conf_note":"Accurately reported opinion.","corr":"","topic":"ST-04; historiography; projectile-mass"},"P3-F121":{"id":"P3-F121","claim":"A 24-pound cannonball was thrown 175 m.","value":"175","unit":"m","sources":["fino1972machines","saimre2006trebuchet","hansen1992experimental"],"pin":"Finó 34–35; Saimre 74–75","quote":"on put envoyer un boulet de 24 livres à 175 m.","conf":"High","conf_note":"Favé's reported measurement, repeated by three scholarly sources.","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; performance-data"},"P3-F021":{"id":"P3-F021","claim":"The city surrendered on Friday 27 Rajab 583 / 2 October 1187.","value":"2 October 1187","unit":"date","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"the city was at last surrendered on Friday, 27 Rajab, A.H. 583/2 October, A.D. 1187","conf":"High","conf_note":"De expugnatione also dates the reading of the agreement to Friday 2 October.","corr":"brundage1962expugnatione","topic":"ST-02; jerusalem-1187; chronology"},"P3-F127":{"id":"P3-F127","claim":"At Tenochtitlan in 1521, with ammunition critically low, Cortés accepted a proposal to build a trebuchet.","value":"1521","unit":"year AD","sources":["chevedden1995trebuchet"],"pin":"71","quote":"As ammunition was running critically low, Cortés eagerly accepted a proposal to build a trebuchet.","conf":"High","conf_note":"Specialist scholars; corroborated by Cortés's letter.","corr":"cortes2004catapult","topic":"ST-15; tenochtitlan-1521; last-use"},"P3-F137":{"id":"P3-F137","claim":"McCotter judges the description to be clearly that of a trebuchet, apart from the absence of the rope-pulling crews.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text after n. 9","quote":"This is clearly a description of a trebuchet and compares well with pictures in medieval manuscripts","conf":"High","conf_note":"Scholarly interpretation, accurately reported.","corr":"","topic":"ST-16; historiography"},"P3-F211":{"id":"P3-F211","claim":"The helepolis may have stood more than 100 feet (about 30 m) tall and was armed with catapults.","value":"100","unit":"feet (about 30 m)","sources":["marino2018rise"],"pin":"","quote":"a wheeled siege tower that may have stood more than 100 feet tall","conf":"Medium","conf_note":"Tier C, consistent with Plutarch's 66 cubits.","corr":"plutarch1920demetrius","topic":"ST-27; rhodes-305; helepolis"},"P3-F138":{"id":"P3-F138","claim":"McCotter suggests the rope-pullers may have been hidden from the bishop by sheaths of iron or, more commonly, leather.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text after n. 9","quote":"they may well have been obscured from his view by the sheaths of iron, or probably more commonly leather","conf":"Medium","conf_note":"Interpretive suggestion, not evidence.","corr":"","topic":"ST-16; crew-protection"},"P3-F174":{"id":"P3-F174","claim":"On the night of 26 September 1687 a Venetian bomb passed through an opening in the roof and ignited the gunpowder stored in the Parthenon.","value":"26 September 1687","unit":"date","sources":["chatziaslanindmorosini","ehrlich2026athens","acropolismuseumndhistory","historytodayndparthenon"],"pin":"","quote":"The Parthenon was also used as a powder magazine, when, on September 26, 1687, Venetian artillery, attacking the Turks from the Hill of the Muses, scored a direct hit.","conf":"High","conf_note":"Three B sources and one C agree on date and cause.","corr":"chatziaslanindmorosini; acropolismuseumndhistory; historytodayndparthenon","topic":"ST-22; athens-1687; explosion"},"P3-F088":{"id":"P3-F088","claim":"Josephus reports that Vespasian set 160 engines for throwing stones and darts around the town.","value":"160","unit":"engines","sources":["josephus1895war"],"pin":"3.166","quote":"The number of the engines was in all a hundred and sixty","conf":"Medium","conf_note":"Single ancient source; plausible for a three-legion army but uncorroborated.","corr":"","topic":"ST-11; jotapata-67; artillery"},"P3-F095":{"id":"P3-F095","claim":"After 1187 the Ayyubids under Saladin, his brother al-ʿAdil and al-ʿAdil's son al-Muʿaẓẓam ʿĪsā built a wall, towers and a moat at Jerusalem.","value":"","unit":"","sources":["wekslerbdolah2011early"],"pin":"446","quote":"the historical sources report the construction of a wall, towers and a moat during the rule of the Ayyubids sultans Saladin, his brother al-Malik al-ʿAdil and his son al-Malik al-Muʾaẓẓam ʿIsa","conf":"High","conf_note":"Archaeologist's synthesis of written sources and building inscriptions.","corr":"","topic":"ST-12; jerusalem-ayyubid; fortifications"},"P3-F074":{"id":"P3-F074","claim":"Crusader machines shot firebrands of wood dipped in pitch, wax and sulfur, with straw and tow fastened by an iron band.","value":"","unit":"","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"The wood was dipped in pitch, wax, and sulphur; then straw and tow were fastened on by an iron band","conf":"Medium","conf_note":"Eyewitness.","corr":"","topic":"ST-09; jerusalem-1099; artillery"},"P3-F124":{"id":"P3-F124","claim":"Lateral deviation of the shots never exceeded about 3 m.","value":"3","unit":"m","sources":["fino1972machines","hansen1992experimental"],"pin":"Finó 34–35","quote":"il n'y eut jamais 3 m. de déviation latérale","conf":"High","conf_note":"Two independent scholarly sources from Favé's report.","corr":"hansen1992experimental","topic":"ST-14; accuracy"},"P3-F204":{"id":"P3-F204","claim":"In 1271 Kublai sent to the Ilkhanate for engine-makers and the Ilkhan sent Alaowading and Yisimayin.","value":"1271","unit":"year AD","sources":["wuyungaowa2012mongol"],"pin":"citing Yuan shi 203","quote":"1271年忽必烈遣使到伊朗向伊利汗国的阿不哥征炮匠。王以阿老瓦丁、亦思马因应诏","conf":"High","conf_note":"Official history as summarized by a specialist; corroborated by Hanson.","corr":"hanson2004mongol","topic":"ST-26; technology-transfer; engineers"},"P3-F047":{"id":"P3-F047","claim":"Modern elasticity theory says the energy stored in a torsion spring is proportional to the cube of the bundle's diameter, which is why the formula needs a cube root.","value":"∝ d³","unit":"","sources":["soedel1979ancient"],"pin":"","quote":"The cubing of the bundle's diameter means that to express the diameter in terms of the mass of the projectile one would have to extract a cube-root.","conf":"High","conf_note":"Engineering analysis by a mechanical engineering professor (Soedel) and historian (Foley).","corr":"maguire2024ancient","topic":"ST-06; catapult-physics; scaling"},"P3-F119":{"id":"P3-F119","claim":"The short end of the arm was only 30 cm long.","value":"0.3","unit":"m","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 74–75","quote":"The machine had a beam of 10.3 m, with the short arm of only 30 cm.","conf":"Medium","conf_note":"Saimre follows Hansen; Finó silent. Unusual ratio (~1:33) – check against Favé's report.","corr":"saimre2006trebuchet","topic":"ST-14; design-parameters"},"P3-F129":{"id":"P3-F129","claim":"Chevedden et al. describe this as the last instance of trebuchet use.","value":"","unit":"","sources":["chevedden1995trebuchet"],"pin":"71","quote":"The last instance of trebuchet use comes from the New World","conf":"Medium","conf_note":"Commonly repeated; 'last' is hard to prove.","corr":"","topic":"ST-15; last-use"},"P3-F235":{"id":"P3-F235","claim":"The Guinness record for the farthest pumpkin fired is 1,690.24 m, by air cannon, in Moab, Utah, on 9 September 2010.","value":"1690.24","unit":"m","sources":["guinnessndfarthest"],"pin":"record page","quote":"The farthest distance to fire a pumpkin is 1,690.24 m (5,545.43 ft)","conf":"High","conf_note":"Guinness World Records (B).","corr":"","topic":"ST-30; records"},"P3-F166":{"id":"P3-F166","claim":"Appian reports that two Athenian slaves (θεράποντες) in the Piraeus wrote down events on lead pieces and slung them to the Romans, repeatedly.","value":"2","unit":"informers","sources":["appian1899mithridatic"],"pin":"Mith. 31","quote":"Two Athenian slaves in the Piræus -- either because they favored the Romans or were looking out for their own safety in an emergency -- wrote down everything that took place there, enclosed their writing in leaden balls, and threw them over to the Romans with slings.","conf":"Medium","conf_note":"Single ancient source, written about two centuries later.","corr":"","topic":"ST-21; athens-86-siege; sling-bullets"},"P3-F092":{"id":"P3-F092","claim":"Josephus says a pregnant woman was struck so hard that the infant was carried half a furlong.","value":"0.5","unit":"furlong (roughly 90–100 m)","sources":["josephus1895war"],"pin":"3.246","quote":"a woman with child had her belly so violently struck, as she was just come out of her house, that the infant was carried to the distance of half a furlong","conf":"Low","conf_note":"Single dramatic claim; likely exaggerated.","corr":"","topic":"ST-11; jotapata-67; artillery-effects; reported-vs-plausible"},"P3-F108":{"id":"P3-F108","claim":"The longest shot with 2,000 kg ballast threw a 15 kg cast-cement ball 168 m.","value":"168","unit":"m","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 75–76","quote":"The longest shot with a ballast of 2000 kg and a ball of 15 kg was 168 m","conf":"High","conf_note":"Measured in trials; reported by Hansen and repeated by Saimre.","corr":"saimre2006trebuchet","topic":"ST-13; performance-data"},"P3-F103":{"id":"P3-F103","claim":"The reconstruction was built in the summer of 1989 at Nykøbing Falster.","value":"1989","unit":"year","sources":["hansen1992experimental","middelaldercentretndprojekt"],"pin":"Hansen, section on construction","quote":"The reconstruction of the medieval trebuchet took place in the summer of 1989.","conf":"High","conf_note":"Museum confirms an original trebuchet built 1989.","corr":"middelaldercentretndprojekt","topic":"ST-13; modern-reconstruction"},"P3-F161":{"id":"P3-F161","claim":"Kennedy built the machine around 1990.","value":"c. 1990","unit":"year","sources":["hadingham2000ready","shropshirestar2008county"],"pin":"Hadingham para. on Kennedy; Star para. 8","quote":"a decade ago, had built his own machine at the top of a sloping farm field","conf":"Medium","conf_note":"Inferred from 'a decade ago' (Jan 2000) and 'about 17 years' before c. 2006.","corr":"shropshirestar2008county","topic":"ST-20; modern-reconstruction"},"P3-F001":{"id":"P3-F001","claim":"Josephus says all the legions had engines but those of the Tenth Legion, both dart- and stone-throwers, were larger and more forcible than the rest.","value":"Tenth Legion","unit":"","sources":["josephus1895war"],"pin":"5.269","quote":"but still more extraordinary ones belonged to the tenth legion: those that threw darts and those that threw stones were more forcible and larger than the rest","conf":"Medium","conf_note":"Reported by Josephus, a Roman-side writer; no independent check of which legion had the best engines.","corr":"","topic":"ST-01; jerusalem-70; roman-artillery"},"P3-F065":{"id":"P3-F065","claim":"The target wall was five feet thick (and, per the newspaper, 20 ft tall and 14 ft wide).","value":"5; 20; 14","unit":"ft","sources":["nova2000secrets","schupp1998timber"],"pin":"transcript (Michael Prestwich); Schupp para. 9","quote":"It's a good five foot thick.","conf":"High","conf_note":"Thickness in both sources; height and width newspaper only.","corr":"schupp1998timber","topic":"ST-08; wall-target"},"P3-F031":{"id":"P3-F031","claim":"Fulton argues that even the largest trebuchets were not effective breaching engines by 1291.","value":"","unit":"","sources":["fulton2016artillery"],"pin":"vii","quote":"even the largest were not effective breaching engines by the time the Franks were pushed out of the Holy Land","conf":"Medium","conf_note":"Contested argument (see Purton).","corr":"purton2018review","topic":"ST-04; breaching; effectiveness"},"P3-F004":{"id":"P3-F004","claim":"Josephus reports that the stones were carried two furlongs and further.","value":"2","unit":"furlongs (stadia)","sources":["josephus1895war"],"pin":"5.270","quote":"were carried two furlongs and further","conf":"Low","conf_note":"Reported range; Marsden's modern estimate of 350–450 m for Roman machines (cited by Arbiv) is of the same order.","corr":"arbiv2023evidence","topic":"ST-01; jerusalem-70; range"},"P3-F032":{"id":"P3-F032","claim":"Purton reports Fulton's view that in every case where a fortress was taken it was by other means, most often mining.","value":"","unit":"","sources":["purton2018review"],"pin":"review","quote":"in every case where a fortress was taken, it was by other means – again, most often, mining","conf":"Medium","conf_note":"Reviewer's summary of a contested argument.","corr":"","topic":"ST-04; mining; effectiveness"},"P3-F162":{"id":"P3-F162","claim":"The machine was 30 tonnes and 60 ft tall.","value":"30; 60 (18)","unit":"tonnes; ft (m)","sources":["shropshirestar2008county","chevedden1995trebuchet"],"pin":"Star para. 5; Chevedden 66–67 (caption)","quote":"It was a 30 tonne, 60ft tall replica of a medieval trebuchet.","conf":"Medium","conf_note":"Height agrees in both sources; 30 t is total mass in the Star but counterweight in Chevedden.","corr":"chevedden1995trebuchet; lienhardndmodern","topic":"ST-20; modern-reconstruction"},"P3-F157":{"id":"P3-F157","claim":"Bennett states that William Embriaco had the Genoese vessels at Jaffa broken up and their timber and nails carried inland and rebuilt as wooden towers.","value":"","unit":"","sources":["bennett2013amphibious"],"pin":"134","quote":"had its vessels broken up and the resulting timber and nails were then carried inland and reconstructed as wooden towers","conf":"Medium","conf_note":"Conflicts in part with Raymond, who says the ships were abandoned to an enemy fleet; Bennett's page has no footnote.","corr":"","topic":"ST-19; jerusalem-1099; materials"},"P3-F084":{"id":"P3-F084","claim":"To fund the war Sulla took sacred treasures from Epidaurus and Olympia and demanded the treasures of Delphi.","value":"","unit":"","sources":["plutarch1916sulla"],"pin":"Sulla 12.3–4","quote":"he diverted to his uses the sacred treasures of Hellas, partly from Epidaurus, and partly from Olympia","conf":"Medium","conf_note":"Single ancient source in this check.","corr":"","topic":"ST-10; athens-86-siege"},"P3-F183":{"id":"P3-F183","claim":"De' Mussi wrote that the besiegers had corpses placed in catapults and lobbed into the city.","value":"","unit":"","sources":["wheelis2002biological"],"pin":"971-975 (de' Mussi in Horrox trans.)","quote":"ordered corpses to be placed in catapults and lobbed into the city in the hope that the intolerable stench would kill everyone inside","conf":"Medium","conf_note":"Second-hand report by a non-eyewitness; Wheelis finds it plausible.","corr":"","topic":"ST-23; biological-warfare"},"P3-F135":{"id":"P3-F135","claim":"John contrasted the inaccurate rope-pulled Avar engines with accurate Byzantine torsion artillery.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text, n. 7 (Mirac. St Demet. XIV.153)","quote":"compares the inaccurate rope-pulled devices of the Avars with the accuracy of the Byzantine torsion artillery","conf":"Medium","conf_note":"Reported judgment of a besieged eyewitness-era author; accuracy not measured.","corr":"","topic":"ST-16; accuracy; torsion-vs-traction"},"P3-F175":{"id":"P3-F175","claim":"About 300 Turks were reported killed by the explosion.","value":"300","unit":"people","sources":["chatziaslanindmorosini","historytodayndparthenon"],"pin":"","quote":"Three hundred Turks were killed by the marble that was launched in all directions.","conf":"Medium","conf_note":"Contemporary reported figure; one B and one C source.","corr":"historytodayndparthenon","topic":"ST-22; athens-1687; casualties"},"P3-F205":{"id":"P3-F205","claim":"Yisimayin placed his engine at the south-east corner of Xiangyang; its shot weighed 150 jin, it shook heaven and earth, destroyed what it struck and sank seven chi into the ground.","value":"150","unit":"jin","sources":["wuyungaowa2012mongol"],"pin":"quoting Yuan shi 203","quote":"置炮于城东南隅，重一百五十斤，机发，声震天地，所击无不摧陷，入地七尺","conf":"Medium","conf_note":"Reported in an official history compiled later; not measured.","corr":"hanson2004mongol","topic":"ST-26; projectile-mass; counterweight-trebuchet"},"P3-F085":{"id":"P3-F085","claim":"Sulla took Athens on the Calends (1st) of March, as he himself said in his Memoirs.","value":"1 March","unit":"date","sources":["plutarch1916sulla"],"pin":"Sulla 14","quote":"He took Athens, as he says himself in his Memoirs, on the Calends of March","conf":"Medium","conf_note":"Plutarch quoting Sulla's lost Memoirs.","corr":"","topic":"ST-10; athens-86-siege; chronology"},"P3-F044":{"id":"P3-F044","claim":"A dactyl is about 19.3 mm (Maguire gives 19.268 mm; Soedel & Foley give about 19.8 mm).","value":"19.27","unit":"mm","sources":["maguire2024ancient","soedel1979ancient"],"pin":"","quote":"and D is the diameter of the torsion spring in dactyls (19.268mm).","conf":"Medium","conf_note":"Sources differ by about 3 percent; the 0.130 coefficient in Paasch & Paasch implies about 19.3 mm.","corr":"paasch2024estimation","topic":"ST-06; units"},"P3-F015":{"id":"P3-F015","claim":"According to Ibn al-Athīr (via Dajani-Shakeel), Saladin's mangonels were installed in one night and working by morning, and the Latins also mounted mangonels on the wall.","value":"","unit":"","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"Salah al-Din installed his mangonels, and by morning his machinery was functional. The Latins also installed their mangonels on the wall","conf":"Medium","conf_note":"Chronicle report summarized by a modern scholar; not checked in the chronicle itself.","corr":"","topic":"ST-02; jerusalem-1187; artillery"},"P3-F081":{"id":"P3-F081","claim":"Plutarch reports that timber ran short because many siege-works collapsed under their own weight or were burnt by the defenders' fire-bolts, so Sulla cut the sacred groves of the Academy and the Lyceum.","value":"","unit":"","sources":["plutarch1916sulla"],"pin":"Sulla 12.3","quote":"he laid hands upon the sacred groves, and ravaged the Academy, which was the most wooded of the city's suburbs, as well as the Lyceum","conf":"Medium","conf_note":"Reported; the Academy part is corroborated by Appian, the Lyceum only by Plutarch.","corr":"appian1899mithridatic","topic":"ST-10; athens-86-siege; timber"},"P3-F223":{"id":"P3-F223","claim":"It was designed by the Danish expert Peter Vemming of the Medieval Centre, Nykøbing.","value":"Peter Vemming","unit":"","sources":["coventrytelegraph2005catapulted","medievalhistories2015warwick"],"pin":"CT para. 3; MH","quote":"Warwick's replica was designed by Danish medieval weapons expert Dr Peter Vemming","conf":"High","conf_note":"Two independent sources; identity with Peter Vemming Hansen inferred.","corr":"medievalhistories2015warwick","topic":"ST-29; modern-reconstruction"},"P3-F012":{"id":"P3-F012","claim":"Ernoul places the first attack on the western wall between David's Gate and St Stephen's Gate.","value":"","unit":"","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"they were stationed opposite the western wall between David's Gate (Bab al-Khalil) and St. Stephen's Gate (Bab al-'Amud)","conf":"Medium","conf_note":"Ernoul as summarized by Dajani-Shakeel; Arabic chroniclers do not give the location.","corr":"","topic":"ST-02; jerusalem-1187"},"P3-F105":{"id":"P3-F105","claim":"Scale models at 1:10 and 1:5 were made before the full-size machine.","value":"1:10; 1:5","unit":"scale","sources":["saimre2006trebuchet"],"pin":"75–76","quote":"Before the construction of the actual machine, two replicas were made, in scales of 1:10 and 1:5.","conf":"High","conf_note":"Scholarly summary of Hansen.","corr":"","topic":"ST-13; modern-reconstruction"},"P3-F208":{"id":"P3-F208","claim":"Demetrius won the title Poliorcetes ('the Besieger') from his unsuccessful siege of Rhodes in 305 BC.","value":"305 BC","unit":"year","sources":["britannicanddemetrius"],"pin":"","quote":"From his unsuccessful siege of Rhodes (305) he won the title Poliorcetes ('the Besieger').","conf":"High","conf_note":"Reference work.","corr":"marino2018rise","topic":"ST-27; rhodes-305; chronology"},"P3-F034":{"id":"P3-F034","claim":"Purton says Fulton wavers, allowing that the largest engines demolished wall tops and threatened the thicker walls below.","value":"","unit":"","sources":["purton2018review"],"pin":"review (citing Fulton 2018, 4 and 404)","quote":"On one of his central theses, he wavers.","conf":"High","conf_note":"Accurately reported opinion.","corr":"","topic":"ST-04; historiography"},"P3-F191":{"id":"P3-F191","claim":"The counterweight stayed between 200 and 300 kg; stones of 2–11.5 kg were used.","value":"200–300; 2–11.5","unit":"kg; kg","sources":["saimre2006trebuchet"],"pin":"76","quote":"Stones of 2–11.5 kg were used as ammunition.","conf":"High","conf_note":"Author's own report.","corr":"","topic":"ST-24; performance-data"},"P3-F101":{"id":"P3-F101","claim":"An-Nāṣir then brought miners into the city and had the fortified parts and the Tower of David demolished before returning to Kerak.","value":"","unit":"","sources":["karakas2024issue"],"pin":"70–71","quote":"Ardından şehre madenciler getirdi. Kudüs'teki müstahkem kısımları ve Dâvud Burcu'nu tahrip ettirip Kerek'e döndü.","conf":"Medium","conf_note":"Footnote cites the Rothelin continuation; our translation ('madenciler' = miners).","corr":"","topic":"ST-12; jerusalem-1239"},"P3-F036":{"id":"P3-F036","claim":"The treatise's contents include a chapter titled 'The Mongonel', as well as battering rams and siege towers.","value":"","unit":"","sources":["zaky1965preliminary"],"pin":"107–9","quote":"13. The Mongonel.","conf":"High","conf_note":"Bibliographic description of the manuscript contents.","corr":"","topic":"ST-05; tarsusi"},"P3-F202":{"id":"P3-F202","claim":"Trebuchet also meant the right to maintain a cucking-stool, attested in 1275 in a claim by the Abbot of Westminster.","value":"1275","unit":"year AD","sources":["anglonorman2025trebuchet"],"pin":"s.v. trebuchet, sense 3","quote":"abbas Westm' clamat habere [...] collistridium, tresbuchet","conf":"High","conf_note":"Scholarly dictionary citation.","corr":"","topic":"ST-25; words; oddities; law"},"P3-F122":{"id":"P3-F122","claim":"A 22 cm shell filled with sand/earth was thrown 145 m.","value":"145","unit":"m","sources":["fino1972machines","saimre2006trebuchet","hansen1992experimental"],"pin":"Finó 34–35; Saimre 74–75","quote":"une bombe de 0,22 m. remplie de terre à 145 m.","conf":"High","conf_note":"As above.","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; performance-data"},"P3-F197":{"id":"P3-F197","claim":"Varbola (1999): 1,400 kg counterweight, 7.5 m beam, 10 kg missile to 120 m.","value":"1400; 7.5; 120","unit":"kg; m; m","sources":["saimre2006trebuchet"],"pin":"75","quote":"According to the enthusiasts themselves the counterweight was 1400 kg, beam length 7.5 m and the machine was capable of hurling a 10 kg missile to a range of 120 m.","conf":"Low","conf_note":"Unpublished builders' claim relayed by Saimre.","corr":"","topic":"ST-24; performance-data"},"P3-F222":{"id":"P3-F222","claim":"The Warwick Castle trebuchet was built in 2005.","value":"2005","unit":"year","sources":["leamingtonobserver2015investigation","ihbc2015warwick","medievalhistories2015warwick"],"pin":"Observer para. 7","quote":"The trebuchet was built in 2005 and is one of the castle's main attractions.","conf":"High","conf_note":"Three independent sources.","corr":"ihbc2015warwick; medievalhistories2015warwick","topic":"ST-29; modern-reconstruction"},"P3-F178":{"id":"P3-F178","claim":"Morosini tried to remove Athena's horses from the west pediment, but they fell and were smashed.","value":"","unit":"","sources":["ehrlich2026athens","chatziaslanindmorosini"],"pin":"","quote":"the masterpieces were smashed to bits on the rock below","conf":"High","conf_note":"Two B sources agree.","corr":"chatziaslanindmorosini","topic":"ST-22; athens-1687; sculpture"},"P3-F026":{"id":"P3-F026","claim":"A petraria built at common expense was called the 'petraria of God', and a priest preaching beside it collected money to restore it and hire men to bring stones.","value":"","unit":"","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"Near it, there constantly preached a priest, a man of great probity, who collected money to restore it at their joint expense, and to hire persons to bring stones for casting.","conf":"Medium","conf_note":"Chronicle report.","corr":"","topic":"ST-03; acre-1191; financing; crews"},"P3-F201":{"id":"P3-F201","claim":"Trebuchet also meant a bird-snare or trap for small birds.","value":"","unit":"","sources":["anglonorman2025trebuchet"],"pin":"s.v. trebuchet, sense 2 (s.xiii2)","quote":"Bird-snare, trap for catching small birds","conf":"High","conf_note":"Scholarly dictionary.","corr":"","topic":"ST-25; words; oddities"},"P3-F006":{"id":"P3-F006","claim":"The stones were white and could be seen (and heard) before they arrived.","value":"","unit":"","sources":["josephus1895war"],"pin":"5.271","quote":"for it was of a white color, and could therefore not only be perceived by the great noise it made, but could be seen also before it came by its brightness","conf":"Medium","conf_note":"Reported by Josephus; plausible for limestone shot but not independently attested.","corr":"","topic":"ST-01; jerusalem-70"},"P3-F209":{"id":"P3-F209","claim":"Plutarch reports the helepolis had a square base 48 cubits a side and rose 66 cubits, tapering from base to summit.","value":"48; 66","unit":"cubits (about 22 m; 30 m)","sources":["plutarch1920demetrius"],"pin":"Demetrius 21","quote":"Its base was square, and each of its sides measured at the bottom forty-eight cubits. It rose to a height of sixty-six cubits","conf":"Medium","conf_note":"Ancient report; Diodorus gives similar base (almost fifty cubits). Metric conversion approximate.","corr":"diodorus1954library; marino2018rise","topic":"ST-27; rhodes-305; helepolis; scale"},"P3-F226":{"id":"P3-F226","claim":"It was described as the world's largest working siege machine.","value":"","unit":"","sources":["ihbc2015warwick","warwickcastlendmighty"],"pin":"IHBC para. 3","quote":"described as the 'world's largest working siege machine'","conf":"Medium","conf_note":"A promotional superlative; the castle now says 'Britain's largest'.","corr":"coventrytelegraph2005catapulted","topic":"ST-29; records"},"P3-F014":{"id":"P3-F014","claim":"The Latin eyewitness says Saladin ordered engines and balistas set up and olive and other branches piled between the city and the engines.","value":"","unit":"","sources":["brundage1962expugnatione"],"pin":"Brundage 1962, 159–63 (Fordham web text)","quote":"He likewise ordered olive branches and branches of other trees to be collected and piled between the city and the engines.","conf":"Medium","conf_note":"Eyewitness report.","corr":"","topic":"ST-02; jerusalem-1187; artillery"},"P3-F164":{"id":"P3-F164","claim":"It lofted objects weighing as much as 500 kg.","value":"500","unit":"kg","sources":["chevedden1995trebuchet"],"pin":"66–67 (caption)","quote":"has lofted objects weighing as much as 500 kilograms","conf":"Medium","conf_note":"Reported in a photo caption.","corr":"","topic":"ST-20; performance-data"},"P3-F159":{"id":"P3-F159","claim":"Godfrey and the Counts of Flanders and Normandy moved their machines overnight, carried in parts almost a mile, to the northern side of the city between the church of St Stephen and the valley of Josaphat.","value":"almost 1","unit":"mile (c. 1.5 km)","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"the machines were carried in parts almost a mile to the place where they were to be set up","conf":"Medium","conf_note":"Eyewitness report; the mile conversion is approximate.","corr":"","topic":"ST-19; jerusalem-1099; logistics"},"P3-F221":{"id":"P3-F221","claim":"According to historical reports cited by the authors, Orban's gun burst, killing Orban and the crew.","value":"","unit":"","sources":["kakaliagos2019damage"],"pin":"481-496","quote":"According to historical reports, Orban's gun had the same fate, killing both Orban and the gun crew.","conf":"Low","conf_note":"Reported story; not independently checked.","corr":"","topic":"ST-28; gunpowder; oddities"},"P3-F120":{"id":"P3-F120","claim":"The counterweight was 4,500 kg: 1,500 kg fixed to the arm and 3,000 kg hanging freely.","value":"4500 (1500 + 3000)","unit":"kg","sources":["fino1972machines","hansen1992experimental","saimre2006trebuchet"],"pin":"Finó 34–35; Saimre 74–75","quote":"The counterweight had a mass of 4500 kg, 1500 kg of which was fixed to the beam and 3000 kg hung freely.","conf":"High","conf_note":"Total in all three; split in Hansen and Saimre.","corr":"fino1972machines; hansen1992experimental","topic":"ST-14; design-parameters"},"P3-F008":{"id":"P3-F008","claim":"The Romans countered by blackening the stones, after which they killed many at one blow.","value":"","unit":"","sources":["josephus1895war"],"pin":"5.273","quote":"by blacking the stone, who then could aim at them with success","conf":"Medium","conf_note":"Reported by Josephus only.","corr":"","topic":"ST-01; jerusalem-70"},"P3-F153":{"id":"P3-F153","claim":"The Gesta says Godfrey and Count Raymond built towers although wood had to be brought from a considerable distance.","value":"","unit":"","sources":["krey1921gesta"],"pin":"Krey 1921 (Fordham web text, Gesta 'The Fall of Jerusalem')","quote":"although it was necessary to bring wood from a considerable distance","conf":"Medium","conf_note":"Eyewitness report; distance unspecified.","corr":"","topic":"ST-19; jerusalem-1099; materials"},"P3-F040":{"id":"P3-F040","claim":"A manuscript of the treatise is Bodleian Library MS. Huntington 264, cataloged as a treatise on weaponry written for Saladin.","value":"MS. Huntington 264","unit":"shelfmark","sources":["bodleian2026treatise","zaky1965preliminary"],"pin":"","quote":"The Treatise on Armoury was written for Saladin (1169-1193 CE), the celebrated founder of the Ayyubid dynasty","conf":"High","conf_note":"Library metadata and Zaky agree on the shelfmark.","corr":"zaky1965preliminary","topic":"ST-05; tarsusi; manuscript"},"P3-F193":{"id":"P3-F193","claim":"Shots were fired from the top of the hillfort, about 35 m above the surrounding terrain.","value":"35","unit":"m","sources":["saimre2006trebuchet"],"pin":"76","quote":"Shots were fired from the top of the hillfort, which is approximately 35 m above the surrounding terrain.","conf":"High","conf_note":"Author's own report.","corr":"","topic":"ST-24; performance-data"},"P3-F128":{"id":"P3-F128","claim":"The machine took several days to build and at its first launch the stone went straight up and came back to smash it.","value":"","unit":"","sources":["chevedden1995trebuchet"],"pin":"71","quote":"The machine took several days to build, and at the first launch the stone went straight up, only to return and smash it.","conf":"Medium","conf_note":"Conflicts with the Nahua account of where the stone fell.","corr":"","topic":"ST-15; failure; release-timing"},"P3-F093":{"id":"P3-F093","claim":"Josephus describes the noise of the engines and their missiles as very terrible.","value":"","unit":"","sources":["josephus1895war"],"pin":"3.247","quote":"The noise of the instruments themselves was very terrible, the sound of the darts and stones that were thrown by them was so also","conf":"Medium","conf_note":"Subjective but consistent with his other descriptions (3.167, 3.243).","corr":"","topic":"ST-11; jotapata-67; artillery-effects"},"P3-F148":{"id":"P3-F148","claim":"Arabic mandjanik comes from Byzantine manganikon, from Greek manganon, a device such as a crane using levers and fulcrums.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"text","quote":"The word used by the Arab historians to describe their catapults is mandjanik, which comes from the Byzantine manganikon","conf":"High","conf_note":"Scholarly etymology.","corr":"","topic":"ST-18; words; arabic"},"P3-F152":{"id":"P3-F152","claim":"At Jerusalem in June 1099 the crusaders faced a severe lack of water and an absence of wood for building siege towers.","value":"","unit":"","sources":["bennett2013amphibious"],"pin":"134","quote":"there was an absence of wood for building siege towers","conf":"Medium","conf_note":"Modern historian's summary; consistent with the Gesta's remark on distant timber.","corr":"krey1921gesta","topic":"ST-19; jerusalem-1099; materials"},"P3-F070":{"id":"P3-F070","claim":"The episode aired on PBS on 1 February 2000.","value":"2000-02-01","unit":"date","sources":["hadingham2000ready","nova2000secrets"],"pin":"Hadingham para. 1","quote":"The episode on trebuchets will air on PBS on February 1 as part of a miniseries on experimental archaeology.","conf":"High","conf_note":"Smithsonian (Jan 2000) and transcript page agree.","corr":"nova2000secrets","topic":"ST-08; modern-reconstruction"},"P3-F089":{"id":"P3-F089","claim":"Josephus reports stones 'of the weight of a talent' thrown by the engines.","value":"1","unit":"talent (about 26 kg)","sources":["josephus1895war","soedel1979ancient"],"pin":"3.167","quote":"stones of the weight of a talent were thrown by the engines that were prepared for that purpose","conf":"Medium","conf_note":"Reported; the talent was a standard ancient caliber for heavy stone-throwers. Metric value derived from Soedel & Foley's three talents = 78 kg.","corr":"","topic":"ST-11; jotapata-67; artillery; projectile-mass"},"P3-F079":{"id":"P3-F079","claim":"Sulla besieged both Athens and its port, the Piraeus, after Athens (under the tyrant Aristion) sided with Mithridates.","value":"","unit":"","sources":["plutarch1916sulla","appian1899mithridatic"],"pin":"Plutarch, Sulla 12.1; Appian, Mith. 30","quote":"Athens was compelled by the tyrant Aristion to side with Mithridates","conf":"High","conf_note":"Two independent ancient accounts agree.","corr":"appian1899mithridatic","topic":"ST-10; athens-86-siege"},"P3-F181":{"id":"P3-F181","claim":"Janibeg renewed the siege of Caffa in 1345 and lifted it after a year when plague devastated his forces.","value":"1345-1346","unit":"years AD","sources":["wheelis2002biological"],"pin":"971-975","quote":"Janibeg renewed the siege in 1345 but was again forced to lift it after a year, this time by an epidemic of plague that devastated his forces.","conf":"High","conf_note":"Peer-reviewed synthesis.","corr":"","topic":"ST-23; caffa-1346; dating"},"P3-F200":{"id":"P3-F200","claim":"In Anglo-Norman, trebuchet meant a siege engine throwing stones from a sling.","value":"","unit":"","sources":["anglonorman2025trebuchet"],"pin":"s.v. trebuchet, sense 1 (s.xiii)","quote":"Siege engine for throwing stones or heavy projectiles from a sling","conf":"High","conf_note":"Scholarly dictionary.","corr":"","topic":"ST-25; words"},"P3-F224":{"id":"P3-F224","claim":"A team of eight built it from 28 tonnes of oak in Wiltshire and moved it to Warwick in 300 pieces.","value":"8; 28; 300","unit":"people; tonnes; pieces","sources":["coventrytelegraph2005catapulted"],"pin":"final para.","quote":"A team of eight experts produced the catapult out of 28 tonnes of solid oak at their base in Wiltshire.","conf":"Medium","conf_note":"Single source for the numbers; Wiltshire firm confirmed by Medieval Histories.","corr":"medievalhistories2015warwick","topic":"ST-29; materials"},"P3-F050":{"id":"P3-F050","claim":"The largest stone-thrower on record was a three-talent (78 kg) machine built by Archimedes; Athenaeus describes it on Hiero's great ship, throwing a stone Gulick renders as 180 pounds or an 18-foot javelin about 600 feet.","value":"78","unit":"kg (three talents)","sources":["soedel1979ancient","athenaeus1928deipnosophists"],"pin":"Athenaeus 5.208c","quote":"It is interesting to note that the largest stone-thrower on record, a three-talent (78 kilogram) machine, was built by Archimedes.","conf":"Medium","conf_note":"Literary report (Athenaeus c. AD 200 quoting an earlier description); Gulick converts units to pounds and feet.","corr":"athenaeus1928deipnosophists","topic":"ST-06; archimedes; catapult-size"},"P3-F077":{"id":"P3-F077","claim":"Raymond reports that two women who tried to bewitch one of the hurling machines were crushed by a stone, together with three slaves.","value":"2 + 3","unit":"people killed","sources":["raymond1921historia"],"pin":"Krey 1921 (Fordham web text, 'The Frankish Victory')","quote":"Two women tried to bewitch one of the hurling machines, but a stone struck and crushed them, as well as three slaves","conf":"Low","conf_note":"Single source; sides and machine ownership not specified in the translation.","corr":"","topic":"ST-09; jerusalem-1099; oddities"},"P3-F207":{"id":"P3-F207","claim":"Marco Polo claimed Saianfu (Xiangyang) was taken thanks to great mangonels built to the Polos' specifications; Britannica calls the episode dubious.","value":"","unit":"","sources":["britannica2026xiangyang"],"pin":"Xiangyang entry (Marco Polo passage)","quote":"The whole episode is dubious, however.","conf":"High","conf_note":"Britannica's judgment accurately reported.","corr":"","topic":"ST-26; marco-polo; source-criticism"},"P3-F167":{"id":"P3-F167","claim":"One message warned Sulla of a next-day infantry sally against his workers and a cavalry attack on both flanks; Sulla set an ambush, killed many and drove the rest into the sea.","value":"","unit":"","sources":["appian1899mithridatic"],"pin":"Mith. 31","quote":"To-morrow the infantry will make a sally in front upon your workers, and the cavalry will attack the Roman army on both flanks.","conf":"Medium","conf_note":"Single ancient source.","corr":"","topic":"ST-21; athens-86-siege; intelligence"},"P3-F027":{"id":"P3-F027","claim":"The 'petraria of God' was credited with shaking down about two poles' length of the wall of the tower Maledictum.","value":"2","unit":"poles (c. 10 m if English poles of 16.5 ft)","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"By means of this engine, a part of the wall of the tower Maledictum was at length shaken down, for about two poles' length.","conf":"Low","conf_note":"Reported, unmeasured; unit conversion assumes the English pole.","corr":"","topic":"ST-03; acre-1191; wall-damage"},"P3-F192":{"id":"P3-F192","claim":"The best shot threw a 5 kg stone 120 m with a 250 kg counterweight.","value":"120","unit":"m","sources":["saimre2006trebuchet"],"pin":"76","quote":"The best shot employed a counterweight of 250 kg and fired a 5 kg stone to a distance of 120 m.","conf":"High","conf_note":"Measured by the experimenter.","corr":"","topic":"ST-24; performance-data"},"P3-F172":{"id":"P3-F172","claim":"On the night of 21–22 September Königsmarck placed 15 guns on the Hill of the Muses, nine on the Pnyx and five enormous mortars on the Areopagus.","value":"15; 9; 5","unit":"guns; guns; mortars","sources":["chatziaslanindmorosini"],"pin":"","quote":"on the hill of the Muses a wall of cannons consisting of 15 guns, on the Pnyx nine, and on the Areos Pagos five enormous mortars","conf":"Medium","conf_note":"Based on contemporary descriptions ('according to descriptions').","corr":"","topic":"ST-22; athens-1687; artillery"},"P3-F144":{"id":"P3-F144","claim":"The siege began in April 1291 and the Mamluks broke into the city on 18 May 1291.","value":"18 May 1291","unit":"date","sources":["cartwright2018siege","skyhistory2026acre"],"pin":"text","quote":"The siege began in April 1291","conf":"High","conf_note":"Standard dating; two independent C sources agree.","corr":"","topic":"ST-17; acre-1291; dating"},"P3-F112":{"id":"P3-F112","claim":"Shots diverged no more than 2–3 m to either side of the line.","value":"2–3","unit":"m","sources":["hansen1992experimental"],"pin":"section on trials","quote":"They did not diverge more than 2-3 m to either side of an ideal line, which is confirmed by the present trials.","conf":"High","conf_note":"Hansen's trials; agrees with Favé's 1850 report.","corr":"fino1972machines","topic":"ST-13; accuracy"},"P3-F057":{"id":"P3-F057","claim":"Langtoft reported thirteen siege engines, and there was in addition a new engine called War Wolf.","value":"13","unit":"engines","sources":["rcahms1963stirlingshire"],"pin":"p. 181, n. 4 (Cal. Docs. Scot. ii, no. 1560)","quote":"in addition to the thirteen siege-engines reported by Langtoft there was another one of novel construction called War Wolf","conf":"Medium","conf_note":"Langtoft's count is a chronicle report.","corr":"","topic":"ST-07; stirling-1304; engine-numbers"},"P3-F102":{"id":"P3-F102","claim":"In 1244 Khwarazmians, with Egyptian aid, captured and sacked Jerusalem (entering on 11 July 1244 according to Karakaş).","value":"1244","unit":"year","sources":["britannica2026crusades","karakas2024issue"],"pin":"Britannica section 'The Crusade of Frederick II'; Karakaş 80–81","quote":"However, in 1244 an alliance of Jerusalem and Damascus failed to prevent the capture and sack of Jerusalem by Khwārezmians with Egyptian aid.","conf":"High","conf_note":"Two sources agree on the event; the day is from Karakaş only.","corr":"karakas2024issue","topic":"ST-12; jerusalem-1244"},"P3-F117":{"id":"P3-F117","claim":"Louis-Napoléon himself designed the sling and specified the curve and mounting of the iron tip.","value":"","unit":"","sources":["hansen1992experimental"],"pin":"section 'Earlier attempts at reconstruction'","quote":"Napoleon himself had designed the sling and specified the curve and mounting of the iron tip.","conf":"Medium","conf_note":"Single scholarly source.","corr":"","topic":"ST-14; modern-reconstruction"},"P3-F182":{"id":"P3-F182","claim":"Gabriele de' Mussi, born about 1280, was a notary in Piacenza.","value":"c. 1280","unit":"year of birth","sources":["wheelis2002biological"],"pin":"971-975","quote":"Gabriele de' Mussi, born circa 1280, practiced as a notary in the town of Piacenza","conf":"High","conf_note":"Peer-reviewed.","corr":"","topic":"ST-23; primary-source; author"},"P3-F110":{"id":"P3-F110","claim":"Ten or twelve people were needed to man the engine.","value":"10–12","unit":"people","sources":["hansen1992experimental","saimre2006trebuchet"],"pin":"Saimre 75–76","quote":"Ten or twelve people are needed to man the engine.","conf":"High","conf_note":"Two scholarly sources.","corr":"saimre2006trebuchet","topic":"ST-13; crews"},"P3-F195":{"id":"P3-F195","claim":"Three trial shots with the same missile landed no more than 2 m apart.","value":"2","unit":"m","sources":["saimre2006trebuchet"],"pin":"76–77","quote":"Three trial shots with the same missile landed in points no further than 2 m from each other.","conf":"High","conf_note":"Measured; small sample.","corr":"","topic":"ST-24; accuracy"},"P3-F002":{"id":"P3-F002","claim":"Josephus reports that the stones thrown weighed a talent.","value":"1","unit":"talent","sources":["josephus1895war"],"pin":"5.270","quote":"the stones that were cast were of the weight of a talent","conf":"Medium","conf_note":"Reported figure; Arbiv's 79-stone assemblage contains only one stone (24 kg) close to a talent, so heavy shots occurred but most were far lighter.","corr":"arbiv2023evidence","topic":"ST-01; jerusalem-70; roman-artillery"},"P3-F046":{"id":"P3-F046","claim":"The optimization of the cord bundle was completed by roughly 270 BC, perhaps by Greek engineers working for the Ptolemaic dynasty in Egypt.","value":"c. 270 BC","unit":"date","sources":["soedel1979ancient"],"pin":"","quote":"This optimization of the cord bundle was completed by roughly 270 B.C., perhaps by the group of Greek engineers working for the Ptolemaic dynasty in Egypt.","conf":"Medium","conf_note":"Authors hedge ('roughly', 'perhaps').","corr":"","topic":"ST-06; catapult-design; chronology"},"P3-F024":{"id":"P3-F024","claim":"The French king rebuilt 'Bad Neighbour' until it broke down part of the principal city wall and shook the tower Maledictum.","value":"","unit":"","sources":["geoffrey1848itinerary"],"pin":"3.7 (Bohn p. 205)","quote":"but the king of France rebuilt it, until by constant blows, he broke down part of the principal city wall, and shook the tower Maledictum","conf":"Medium","conf_note":"Partisan chronicle claim of damage.","corr":"","topic":"ST-03; acre-1191; wall-damage"},"P3-F187":{"id":"P3-F187","claim":"Wheelis concludes the siege of Caffa probably had no more than anecdotal importance in the spread of plague to Europe.","value":"","unit":"","sources":["wheelis2002biological"],"pin":"971-975","quote":"probably had no more than anecdotal importance in the spread of plague","conf":"High","conf_note":"Accurately reported conclusion.","corr":"","topic":"ST-23; black-death; source-criticism"},"P3-F149":{"id":"P3-F149","claim":"Manganikon is first used in the Chronicon Paschale for the Avar machines at the siege of Constantinople in 626.","value":"626","unit":"year AD","sources":["mccotter2003byzantines"],"pin":"text","quote":"The word is first used in the Chronicon Paschale describing the Avar machines at the siege of Constantinople in 626.","conf":"High","conf_note":"Scholarly claim.","corr":"","topic":"ST-18; words; constantinople-626"},"P3-F236":{"id":"P3-F236","claim":"Steve Seigars, a dentist from Greenfield, New Hampshire, built and ran Yankee Siege.","value":"Steve Seigars","unit":"","sources":["pratt2008pumpkin","ap2016pumpkins"],"pin":"Pratt para. 1; AP para. on Yankee Siege II","quote":"","conf":"High","conf_note":"Two independent C sources agree.","corr":"ap2016pumpkins","topic":"ST-30; modern-record"},"P3-F218":{"id":"P3-F218","claim":"Kakaliagos and Ninis estimated the gunpowder charge at 177 kg and placed the gun 500 m from the inner walls.","value":"177; 500","unit":"kg; m","sources":["kakaliagos2019damage"],"pin":"481 (abstract)","quote":"the gunpowder charge p was estimated at 177 kg, and the gun was placed at 500 m from the Inner Walls","conf":"Medium","conf_note":"Modeling estimate; a table gives 117 kg.","corr":"","topic":"ST-28; gunpowder; engineering-model"},"P3-F219":{"id":"P3-F219","claim":"Their reconstruction fired a granite cannonball 752 mm in diameter weighing about 600 kg.","value":"600","unit":"kg","sources":["kakaliagos2019damage"],"pin":"481-496","quote":"adequate to fire a granite cannonball with a diameter at 752 mm and a corresponding projectile weight B of 600 kg","conf":"Medium","conf_note":"Estimate derived from historical reports.","corr":"","topic":"ST-28; projectile-mass; gunpowder"},"P3-F216":{"id":"P3-F216","claim":"The Ottomans breached Constantinople's ancient land wall after a 55-day siege; the city fell on 29 May 1453.","value":"55","unit":"days","sources":["britannica2026constantinople"],"pin":"summary","quote":"The Byzantine Empire came to an end when the Ottomans breached Constantinople's ancient land wall after besieging the city for 55 days.","conf":"High","conf_note":"Reference work.","corr":"","topic":"ST-28; constantinople-1453; dating"},"P3-F233":{"id":"P3-F233","claim":"Seigars and construction engineer Chuck Willard built it as a promotion for his farm stand.","value":"","unit":"","sources":["nhbr2004pumpkin"],"pin":"paras. 6, 11","quote":"Seigars and Willard built the trebuchet a couple of years ago as a promotion for his Yankee Farmer Farmstand on Route 31.","conf":"High","conf_note":"Builder's own account in a newspaper.","corr":"pratt2008pumpkin","topic":"ST-30; modern-reconstruction"},"P3-F188":{"id":"P3-F188","claim":"The Otepää trebuchet was erected in August 2002 for experiments organized by Saimre.","value":"2002","unit":"year","sources":["saimre2006trebuchet"],"pin":"76","quote":"In August 2002 a trebuchet reconstruction was erected on Otepää hillfort","conf":"High","conf_note":"Author's own report.","corr":"","topic":"ST-24; modern-reconstruction"},"P3-F059":{"id":"P3-F059","claim":"Edward ordered that none of his men enter the castle until it had been struck by War Wolf.","value":"","unit":"","sources":["rcahms1963stirlingshire"],"pin":"p. 181, n. 6 (Cal. Docs. Scot. ii, no. 1560)","quote":"Edward gave orders that none of his men were to enter the Castle until it had been struck with the new weapon 'War Wolf'","conf":"High","conf_note":"Documentary basis; HES agrees Edward refused the surrender.","corr":"macivor2024war","topic":"ST-07; stirling-1304; surrender"},"P3-F170":{"id":"P3-F170","claim":"Torsion catapults were probably in storage at Athens by 330/29 BC and definitely by 306/5 BC, according to the Athenian inventories.","value":"306/5 BC","unit":"year","sources":["campbell2011ancient"],"pin":"681","quote":"torsion catapults of some description were probably in storage at Athens by 330/29 b.c., and were definitely there by 306/5 b.c.","conf":"High","conf_note":"Peer-reviewed article based on inscribed inventories.","corr":"","topic":"ST-21; athens; catapults"},"P3-F003":{"id":"P3-F003","claim":"A talent is taken as 26 kg (Arbiv, citing Shatzman 1995).","value":"26","unit":"kg","sources":["arbiv2023evidence"],"pin":"114–15","quote":"According to Shatzman (1995), a talent equals 26 kg","conf":"Medium","conf_note":"Conversion depends on which talent standard is assumed; ancient standards varied.","corr":"","topic":"ST-01; units"},"P3-F198":{"id":"P3-F198","claim":"Anglo-Norman trebucher meant to hurl or cast down, plunge, cause to fall; also to strike down and to overturn or capsize.","value":"","unit":"","sources":["anglonorman2025trebucher"],"pin":"s.v. trebucher, senses 1, 3, 4","quote":"To hurl or cast down, plunge, cause to fall","conf":"High","conf_note":"Scholarly dictionary.","corr":"etymonline2026trebuchet","topic":"ST-25; words; etymology"},"P3-F063":{"id":"P3-F063","claim":"The trebuchets were built in autumn 1998 at Urquhart Castle, Loch Ness.","value":"1998","unit":"year","sources":["schupp1998timber","nova2000secrets"],"pin":"Schupp para. 1–3","quote":"47 hours after I flew out of Redmond, I arrived at Urquhart Castle, on the shores of Lock Ness.","conf":"High","conf_note":"Participant left 15 October (1998 per article date); NOVA confirms the location.","corr":"nova2000secrets","topic":"ST-08; modern-reconstruction"},"P3-F225":{"id":"P3-F225","claim":"It stood 18 m (60 ft) high and weighed 22 tonnes.","value":"18 (60); 22","unit":"m (ft); tonnes","sources":["leamingtonobserver2015investigation","ihbc2015warwick","coventrytelegraph2005catapulted","smith2022warwick"],"pin":"Observer para. 7","quote":"It stands 60ft high, weighs 22 tonnes and has been fired some 6,500 times.","conf":"High","conf_note":"Several independent sources (Medieval Histories says 19 m).","corr":"ihbc2015warwick; coventrytelegraph2005catapulted; smith2022warwick","topic":"ST-29; design-parameters"},"P3-F238":{"id":"P3-F238","claim":"At the 2004 World Championship Punkin Chunkin, Yankee Siege threw a pumpkin 1,394 ft (425 m).","value":"1394","unit":"ft","sources":["nhbr2004pumpkin","npr2005pumpkin"],"pin":"NHBR para. 2; NPR photo caption","quote":"It set a world record in 2004, when this photo was taken, with a throw of 1,394 feet.","conf":"Medium","conf_note":"Competition result reported by two independent outlets (NHBR gives 1,394.29 ft and says it won its category; NPR calls it a world record).","corr":"npr2005pumpkin","topic":"ST-30; modern-record"},"P3-F099":{"id":"P3-F099","claim":"In December 1239 an-Nāṣir Dāwūd's Ayyubid army entered the unwalled city and took a crusader-built stronghold after a 21-day siege (7 December).","value":"21","unit":"days","sources":["karakas2024issue"],"pin":"70","quote":"Surları olmayan Kudüs'e giren Eyyûbî ordusu, Haçlıların bina ettikleri kaleyi 21 gün muhasaranın ardından 7 Aralık 1239 Çarşamba günü kılıç zoruyla teslim aldılar.","conf":"Medium","conf_note":"Single peer-reviewed secondary source read; Turkish original, our translation.","corr":"","topic":"ST-12; jerusalem-1239"},"P3-F083":{"id":"P3-F083","claim":"Appian reports that Thebes supplied Sulla with iron, catapults and other siege apparatus.","value":"","unit":"","sources":["appian1899mithridatic"],"pin":"Mith. 30","quote":"Artifices and apparatus of all kinds, iron, catapults, and everything of that sort were supplied by Thebes.","conf":"Medium","conf_note":"Single ancient source.","corr":"","topic":"ST-10; athens-86-siege; logistics"},"P3-F118":{"id":"P3-F118","claim":"The throwing arm was 10.3 m long.","value":"10.3","unit":"m","sources":["fino1972machines","hansen1992experimental","saimre2006trebuchet"],"pin":"Finó 34–35; Saimre 74–75","quote":"La verge avait 10,30 m. de long","conf":"High","conf_note":"Three sources agree.","corr":"hansen1992experimental; saimre2006trebuchet","topic":"ST-14; design-parameters"},"P3-F186":{"id":"P3-F186","claim":"Wheelis judges that if the corpses were hurled, this was probably how plague passed from besiegers to besieged.","value":"","unit":"","sources":["wheelis2002biological"],"pin":"971-975","quote":"this biological attack was probably responsible for the transmission of the disease from the besiegers to the besieged","conf":"Medium","conf_note":"A scholarly judgment, not proof.","corr":"","topic":"ST-23; biological-warfare; epidemiology"},"P3-F043":{"id":"P3-F043","claim":"In SI units the stone-thrower formula is f = 0.130·∛w, with f the washer (spring) diameter in meters and w the stone mass in kilograms; the original used Attic-Euboic minae of 436.6 g.","value":"0.13","unit":"m per kg^(1/3)","sources":["paasch2024estimation"],"pin":"3 (eq. 3)","quote":"The original design formula used the units of Attic-Euboic minae, where 1 mina = 436.6 grammes","conf":"High","conf_note":"Peer-reviewed; we checked the conversion arithmetic.","corr":"soedel1979ancient","topic":"ST-06; catapult-design; units"},"P3-F066":{"id":"P3-F066","claim":"The wall stood about 200 yards from the machines.","value":"200 (183)","unit":"yd (m)","sources":["nova2000secrets","schupp1998timber"],"pin":"transcript","quote":"Their task - to build siege machines capable of destroying a castle wall at a range of about 200 yards.","conf":"High","conf_note":"Both sources.","corr":"schupp1998timber","topic":"ST-08; performance-data"},"P3-F220":{"id":"P3-F220","claim":"The model reproduced the breach length given in historical reports.","value":"","unit":"","sources":["kakaliagos2019damage"],"pin":"481 (abstract)","quote":"successfully calculating the length of the breach in the wall, referred in historical reports","conf":"Medium","conf_note":"Model validation against reported, not measured, data.","corr":"","topic":"ST-28; engineering-model; validation"},"P3-F018":{"id":"P3-F018","claim":"Dajani-Shakeel states that the 1187 breach was at the same spot where the First Crusaders had entered in 1099.","value":"","unit":"","sources":["dajanishakeel1988medieval"],"pin":"Fordham web text (no page numbers)","quote":"The breach in the wall was in the same spot from which the first Crusaders had entered the city in 1099.","conf":"Medium","conf_note":"Scholar's statement; underlying source not shown in the web text. Worth checking against Gibson and Lewis (2023).","corr":"","topic":"ST-02; jerusalem-1187; jerusalem-1099"},"P3-F053":{"id":"P3-F053","claim":"Vitruvius gives a table of spring-hole sizes by stone weight, starting with a two-pound stone needing a hole five digits wide; later figures in the table are corrupt.","value":"5","unit":"digits for a 2-pound stone","sources":["vitruvius1826architecture"],"pin":"10.11.3","quote":"A balista capable of throwing a stone of two pounds should have the hole (foramen) in the capital five digits wide","conf":"Low","conf_note":"Manuscript figures are partly corrupt (editor's note on LacusCurtius); Roman pounds and digits, not minas and dactyls.","corr":"","topic":"ST-06; catapult-design; primary-source"},"P3-F136":{"id":"P3-F136","claim":"The engines were four-sided, narrowing from broad bases to tops carrying massive cylinders sheathed in iron, to which beams fitted with slings were attached.","value":"","unit":"","sources":["mccotter2003byzantines"],"pin":"n. 8-9 (Mirac. St Demet. XIV.153, Howard-Johnston trans.)","quote":"they were four-sided; they rose from broader bases to narrower tops on which there were massive cylinders, their ends sheathed with a thick layer of iron","conf":"Medium","conf_note":"Primary-source description in translation.","corr":"","topic":"ST-16; machine-anatomy; traction-trebuchet"},"P3-F199":{"id":"P3-F199","claim":"English trebuchet comes from Middle English trebochet, from Anglo-French trebuchet; first known use 15th century.","value":"15th century","unit":"first known use","sources":["merriamwebster2026trebuchet"],"pin":"Etymology; First Known Use","quote":"","conf":"High","conf_note":"Reference dictionary.","corr":"etymonline2026trebuchet","topic":"ST-25; words; etymology"},"P3-F140":{"id":"P3-F140","claim":"The great engine was collected at Ḥiṣn al-Akrād (Krak des Chevaliers) and called 'the Victorious'.","value":"the Victorious","unit":"","sources":["zaimeche2005hama","cartwright2018siege"],"pin":"Zaimeche n. 159; Cartwright text","quote":"One of these massive catapults was taken from Krak des Chevaliers; called 'Victorious'","conf":"Medium","conf_note":"Two independent tier-C sources agree; both derive from Abu'l-Fida.","corr":"","topic":"ST-17; acre-1291; named-engines"},"P3-F091":{"id":"P3-F091","claim":"Josephus says a man standing beside him on the wall had his head carried away by a stone and his skull flung three furlongs.","value":"3","unit":"furlongs (stadia; roughly 550–600 m)","sources":["josephus1895war"],"pin":"3.245","quote":"his head was carried away by such a stone, and his skull was flung as far as three furlongs","conf":"Low","conf_note":"Single, dramatic eyewitness claim; distance very likely exaggerated.","corr":"","topic":"ST-11; jotapata-67; artillery-effects; reported-vs-plausible"},"P3-F217":{"id":"P3-F217","claim":"The great gun was ordered by Mehmed II and made by Orban, a master craftsman from Hungary.","value":"","unit":"","sources":["kakaliagos2019damage"],"pin":"481-496","quote":"The Gun was ordered by Sultan Mehmet II and manufactured by Orban, a skilled master craftsman from Hungary.","conf":"High","conf_note":"Peer-reviewed; standard account.","corr":"","topic":"ST-28; gunpowder; orban"},"P3-F168":{"id":"P3-F168","claim":"Appian reports that Sulla's catapults each discharged twenty of the heaviest lead balls at one volley, making Archelaus's tower untenable so that it was drawn back.","value":"20","unit":"lead balls per volley","sources":["appian1899mithridatic","campbell2011ancient"],"pin":"Appian, Mith. 34; Campbell 697–698","quote":"Sulla, by means of his catapults, each of which discharged twenty of the heaviest leaden balls at one volley","conf":"Low","conf_note":"Single ancient source; meaning disputed (salvo vs multiple shot per throw).","corr":"","topic":"ST-21; athens-86-siege; catapults; sling-bullets"},"P3-F054":{"id":"P3-F054","claim":"Edward I began the siege of Stirling Castle on 21 April 1304.","value":"21 April 1304","unit":"date","sources":["rcahms1963stirlingshire"],"pin":"p. 180","quote":"Edward began the siege of Stirling Castle on 21st April 1304","conf":"High","conf_note":"Heritage inventory based on royal records.","corr":"macivor2024war","topic":"ST-07; stirling-1304; dating"},"P3-F179":{"id":"P3-F179","claim":"Morosini abandoned Athens on 8 April 1688.","value":"8 April 1688","unit":"date","sources":["chatziaslanindmorosini","historytodayndparthenon"],"pin":"","quote":"On April 8, Morosini abandoned the deserted city.","conf":"High","conf_note":"B source; History Today agrees the Venetians left a year later.","corr":"historytodayndparthenon","topic":"ST-22; athens-1687; chronology"},"P3-F011":{"id":"P3-F011","claim":"De expugnatione dates the start of the siege to 20 September 1187.","value":"20 September 1187","unit":"date","sources":["brundage1962expugnatione"],"pin":"Brundage 1962, 159–63 (Fordham web text)","quote":"The Holy City of Jerusalem was besieged on September 20.","conf":"Medium","conf_note":"Arabic sources (via Dajani-Shakeel) give 21 September and Ernoul 18 September for Saladin's arrival.","corr":"dajanishakeel1988medieval","topic":"ST-02; jerusalem-1187; chronology"},"P3-F100":{"id":"P3-F100","claim":"The Tower of David garrison under Richard of Argentan held out until its supplies ran out and surrendered on 13 December 1239 with safe conduct to the coast.","value":"13 December 1239","unit":"date","sources":["karakas2024issue"],"pin":"70","quote":"Dâvud Burcu'ndaki Richard of Argentan komutasındaki garnizon ise erzakları tükeninceye kadar direndi.","conf":"Medium","conf_note":"Single secondary source read.","corr":"","topic":"ST-12; jerusalem-1239"},"P3-F180":{"id":"P3-F180","claim":"In 1686, facing Morosini's threat, the Ottomans dismantled the Temple of Athena Nike to reinforce the Acropolis defenses.","value":"1686","unit":"year","sources":["acropolismuseumndhistory"],"pin":"","quote":"in 1686, the Turks, facing a threat from the Venetian army led by General Morosini, dismantled the Temple of Athena Nike","conf":"High","conf_note":"Museum source.","corr":"","topic":"ST-22; athens-1687; acropolis"},"P3-F176":{"id":"P3-F176","claim":"The Acropolis burned through the night of 26–27 September and the whole of the next day.","value":"","unit":"","sources":["chatziaslanindmorosini"],"pin":"","quote":"The entire night of September 26 (towards the 27th) as well as the entire next day, the Acropolis burned.","conf":"Medium","conf_note":"Single B source.","corr":"","topic":"ST-22; athens-1687"},"P3-F177":{"id":"P3-F177","claim":"Morosini, reporting to the Venetian government, called it 'a fortunate shot'.","value":"","unit":"","sources":["ehrlich2026athens"],"pin":"","quote":"Francesco Morosini, the commander in chief, when reporting to the Venetian government, called it \"a fortunate shot.\"","conf":"High","conf_note":"Reference work quoting the report.","corr":"","topic":"ST-22; athens-1687"},"P3-F068":{"id":"P3-F068","claim":"A throw was clocked by radar at 126–127 mph.","value":"126–127 (56–57)","unit":"mph (m/s)","sources":["schupp1998timber","nova2000secrets"],"pin":"Schupp para. 11; transcript","quote":"the second boulder flew about 200 yards, clocked on the radar gun at 126 miles per hour","conf":"High","conf_note":"Two independent sources within 1 mph.","corr":"nova2000secrets","topic":"ST-08; phase6-data"},"P3-F087":{"id":"P3-F087","claim":"Jotapata (Yodefat) fell to the Romans in July AD 67 after a 47-day siege.","value":"47","unit":"days","sources":["strauss2022siege"],"pin":"","quote":"In July of 67, Yodefat fell to the Romans after a 47-day siege.","conf":"High","conf_note":"Expert secondary source; duration ultimately from Josephus.","corr":"","topic":"ST-11; jotapata-67; chronology"}};
